import sys

def solve():
    def is_divisible_by_three(n):
        return n % 3 == 0

    def can_vanya_win(n):
        return is_divisible_by_three(n) or n <= 2

    def can_vova_win(n, moves):
        return moves >= 10 and not is_divisible_by_three(n)

    def min_moves_to_win(n):
        if n <= 2:
            return 0
        if is_divisible_by_three(n):
            return 1
        if n == 3:
            return 2
        moves = [float('inf')] * (n + 1)
        moves[1] = 0
        moves[2] = 1
        for i in range(3, n + 1):
            moves[i] = min(moves[i - 1] + 1, moves[i - 2] + 2)
            if not is_divisible_by_three(i - 1):
                moves[i] = min(moves[i], moves[i - 3] + 3)
        return moves[n]

    t = int(input())
    for _ in range(t):
        n = int(input())
        if can_vanya_win(n):
            print("First")
        elif can_vova_win(n, min_moves_to_win(n)):
            print("Second")
        else:
            print("Draw")

