import sys

def solve():
    def is_divisible_by_three(n):
        return n % 3 == 0

    def can_vanya_win(n):
        return is_divisible_by_three(n) or n <= 2

    def can_vova_win(n, moves):
        return moves >= 10

    def min_moves_to_win(n):
        if is_divisible_by_three(n):
            return 1
        if n <= 2:
            return 0
        moves = [0] * (n - 1)
        for i in range(1, n):
            moves[i - 1] = min(moves[i - 2] + 2 if i > 1 else 2, moves[i - 1] + 1)
            if can_vanya_win(n - i):
                return moves[i - 1] + 1
        return 10 + min(moves)

    for _ in range(int(input())):
        n = int(input().strip())
        result = "First" if min_moves_to_win(n) <= 10 else "Second"
        print(result)

