import itertools

def solve():
    n, k = map(int, input().split())
    s = input()

    def count_b(s):
        return s.count('B')

    def replace(s, i, c):
        return s[:i] + c * (len(s) - i) + s[len(s) - (len(s) - i):]

    operations = []
    for i in range(1, n + 1):
        if count_b(s) + (n - i) <= k:
            operations.append((i, 'A'))
            k += n - i
        elif count_b(s) + (k - count_b(s)) <= i:
            operations.append((i, 'B'))
            k -= count_b(s)
        else:
            for c, count in itertools.groupby(reversed(s)):
                if c == 'B':
                    operations.append((i + sum(1 for j in range(1, i) if count[1] > j), 'A'))
                    k += j
                    break
            else:
                operations.append((i, 'B'))
                k += 1

    print(len(operations))
    for operation in operations:
        print(*operation)

import heapq

def solve():
    def dijkstra(graph, start):
        distances = {node: float('inf') for node in graph}
        distances[start] = 0
        priority_queue = [(0, start)]

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in graph[current_node].items():
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

        return distances

    def create_graph(points):
        graph = {}
        for i in range(len(points)):
            x, y = points[i]
            for j in range(i + 1, len(points)):
                graph.setdefault(i, {})[(j,)] = abs(x - points[j][0]) + abs(y - points[j][1])
                graph.setdefault(j, {})[(i,)] = abs(x - points[i][0]) + abs(y - points[i][1])

        return graph

    def find_path(distances):
        path = []
        visited = set()
        start = min(distances, key=distances.get)
        visited.add(start)
        path.append((start // 2, start % 2))

        for i in range(len(distances)):
            if i in visited:
                continue

            min_distance = float('inf')
            min_index = None

            for j in range(len(distances)):
                if j in visited:
                    continue

                distance = distances[j]
                if distance < min_distance:
                    min_distance = distance
                    min_index = j

            path.append((min_index // 2, min_index % 2))
            visited.add(min_index)

        return path

    t = int(input())

    for _ in range(t):
        n = int(input())
        points = [tuple(map(int, input().split())) for _ in range(2 * n)]
        graph = create_graph(points)
        distances = dijkstra(graph, 0)
        min_distance = min(distances.values())
        path = find_path(distances)
        print(min_distance)
        for point in path:
            print(*point)

import heapq

def solve():
    def manhattan_distance(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def dijkstra(points):
        inf = float('inf')
        dist = {p: inf for p in points}
        prev = {p: None for p in points}
        dist[points[0]] = 0
        q = [(0, points[0])]

        while q:
            d, current = heapq.heappop(q)
            if d > dist[current]:
                continue
            for neighbor, weight in enumerate(points):
                if current == neighbor:
                    continue
                new_dist = dist[current] + manhattan_distance(current, neighbor)
                if new_dist < dist[neighbor]:
                    dist[neighbor] = new_dist
                    prev[neighbor] = current
                    heapq.heappush(q, (new_dist, neighbor))

        return dist, prev

    def find_path(dist, prev, start, end):
        path = [end]
        while path[-1] != start:
            path.append(prev[path[-1]])
        path.reverse()
        return path

    def main():
        t = int(input())
        for _ in range(t):
            n = int(input())
            points = list(map(int, input().split()))
            points = [(points[2*i], points[2*i+1]) for i in range(n)]
            dist, prev = dijkstra(points)
            min_dist = dist[points[0]]
            path = find_path(dist, prev, points[0], points[0])
            print(min_dist)
            for p in path:
                print(*p)

    main()

