import heapq

def solve():
    def manhattan_distance(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    def dijkstra(graph, start):
        distances = {start: 0}
        unvisited = set(graph.keys())
        queue = [(0, start)]

        while unvisited:
            current_distance, current_node = heapq.heappop(queue)
            if current_node in unvisited:
                unvisited.remove(current_node)
                for neighbor, weight in graph[current_node].items():
                    distance = current_distance + weight
                    if neighbor not in distances or distance < distances[neighbor]:
                        distances[neighbor] = distance
                        heapq.heappush(queue, (distance, neighbor))

        return distances

    def find_path(points):
        graph = {}
        for i in range(len(points)):
            for j in range(i + 1, len(points)):
                key = (points[i], points[j]) if i < j else (points[j], points[i])
                if key not in graph:
                    graph[key] = {}
                graph[key][(i, j)] = manhattan_distance(points[i], points[j])
                graph[key][(j, i)] = manhattan_distance(points[j], points[i])

        distances = dijkstra(graph, 0)
        path = []
        for i in range(len(points)):
            min_distance = float('inf')
            min_index = -1
            for j in range(len(points)):
                if j not in path and distances[j] + manhattan_distance(points[i], points[j]) < min_distance:
                    min_distance = distances[j] + manhattan_distance(points[i], points[j])
                    min_index = j
            path.append(min_index)

        return path

    t = int(input())
    for _ in range(t):
        n = int(input())
        points = list(map(int, input().split()))
        path = find_path(points)
        print(sum(manhattan_distance(points[i], points[i + 1]) for i in range(len(path) - 1)))
        for point in path:
            print(*points[point])

from collections import defaultdict

def solve():
    def dfs(x, y, k, visited, cache):
        if x == y and visited[y]:
            return 0
        if x == y and not visited[y]:
            return k + 1
        if (x, y, k) in cache:
            return cache[(x, y, k)]
        min_time = float('inf')
        for dx in [-1, 1]:
            nx = x + dx
            if 0 <= nx <= 100 and nx not in visited:
                visited[nx] = True
                time = dfs(nx, y, k - 1, visited, cache)
                if time != float('inf'):
                    min_time = min(min_time, time + 1)
                visited[nx] = False
        if min_time == float('inf'):
            min_time = k + 1
        cache[(x, y, k)] = min_time
        return min_time

    visited = defaultdict(bool)
    cache = {}
    t = int(input())
    for _ in range(t):
        x, y, k = map(int, input().split())
        print(dfs(0, y, k, visited, cache))

