from typing import List

def solve():
    def dijkstra(graph, start, end):
        dist = {start: 0}
        queue = [(0, start)]
        visited = set()

        while queue:
            curr_dist, curr_node = heapq.heappop(queue)

            if curr_node in visited:
                continue

            visited.add(curr_node)

            for neighbor, weight in graph[curr_node].items():
                new_dist = curr_dist + weight

                if neighbor not in dist or new_dist < dist[neighbor]:
                    dist[neighbor] = new_dist
                    heapq.heappush(queue, (new_dist, neighbor))

        return dist[end]

    def can_pick_up(node, key_node, chest_node, k):
        return abs(node - key_node) + abs(node - chest_node) <= k

    def can_move(node, k):
        return k >= abs(node - chest_node)

    graph = defaultdict(lambda: {})
    graph[chest_node][chest_node] = 0
    graph[key_node][key_node] = 0

    for node in range(1, 101):
        if can_pick_up(node, key_node, chest_node, k):
            graph[chest_node][node] = 0
            graph[node][chest_node] = 0

    for node in range(1, 101):
        if can_move(node, k):
            graph[node][node - 1] = 1
            graph[node][node + 1] = 1

    return dijkstra(graph, 0, chest_node)

