from typing import List

def solve():
    def dijkstra(graph, start, end):
        distances = {start: 0}
        unvisited = set(graph.keys())
        while unvisited:
            current = min(unvisited, key=lambda node: distances.get(node, float('inf')))
            unvisited.remove(current)
            for neighbor, weight in graph[current].items():
                distance = distances[current] + weight
                if neighbor not in distances or distance < distances[neighbor]:
                    distances[neighbor] = distance
        return distances[end]

    def can_reach(graph, start, end, capacity):
        return dijkstra(graph, start, end) <= capacity

    def shortest_path(graph, start, end, capacity):
        if not can_reach(graph, start, end, capacity):
            return float('inf')
        return dijkstra(graph, start, end)

    def treasure_chest(x, y, k):
        graph = defaultdict(lambda: {})
        graph[0][x] = 1
        graph[x][0] = 1
        graph[x][y] = -1

        left_move = 1
        right_move = 1
        pick_up = 0
        put_down = 0
        open_chest = 0

        def move(direction, weight):
            new_x = x + direction * left_move
            if new_x in graph:
                graph[new_x][x] = weight
                graph[x][new_x] = weight
                x = new_x

        def pick_up_key():
            nonlocal pick_up
            pick_up += 1

        def put_down_chest():
            nonlocal put_down
            put_down += 1

        def open_chest():
            nonlocal open_chest
            open_chest += 1
            if open_chest == 1:
                return 0

        time = 0
        while True:
            if x == y:
                if pick_up >= 1:
                    time += open_chest()
                    break
            time += 1
            if time > k:
                return float('inf')
            if time - put_down >= k:
                if x != 0:
                    move(-1, right_move)
                else:
                    right_move = 0
                    left_move = 1
                    pick_up_key()
                    continue
            if time - put_down <= k - left_move:
                move(1, left_move)
            else:
                put_down_chest()
                left_move = k - time + put_down
                right_move = 1
                pick_up_key()

        return time

    test_cases = int(input())
    for _ in range(test_cases):
        x, y, k = map(int, input().split())
        print(treasure_chest(x, y, k))

