import sys

def solve():
    def go(x, k):
        return min(abs(x), k)

    def pick_up(x, k):
        return 0

    def put_down(x, k):
        return 0

    def open_chest(x, k):
        return 0

    def move(x, y, k, direction):
        if direction == 'L':
            return x - 1, k - go(x, k)
        else:
            return x + 1, k - go(x, k)

    def pick_key(x, k):
        if x == y:
            return k - pick_up(x, k), True
        else:
            return k, False

    def open_chest_if_possible(x, k, has_key):
        if has_key and x == chest_location:
            return k - open_chest(x, k), True
        else:
            return k, False

    def solve_helper(x, y, k, time, has_key):
        if x == chest_location and has_key:
            return time
        if time > k:
            return float('inf')
        next_x, next_k = move(x, y, k, 'L')
        next_time, next_has_key = pick_key(next_x, next_k)
        next_time = min(next_time, solve_helper(next_x, y, next_k, next_time, next_has_key))
        next_x, next_k = move(x, y, k, 'R')
        next_time, next_has_key = pick_key(next_x, next_k)
        next_time = min(next_time, solve_helper(next_x, y, next_k, next_time, next_has_key))
        next_time, next_has_key = open_chest_if_possible(x, k, has_key)
        return min(next_time, solve_helper(x, y, k, next_time, next_has_key))

    chest_location, key_location, k = map(int, input().strip().split())
    print(solve_helper(0, key_location, k, 0, False))

import collections

def solve():
    n = int(input())
    plays = input().strip()

    # Count the number of wins for each player
    player_wins = collections.Counter(plays)

    # If one player has more wins than the other, return the winner
    if player_wins['A'] > player_wins['B']:
        return 'A'
    elif player_wins['B'] > player_wins['A']:
        return 'B'

    # If both players have the same number of wins, check if either player has won more than half of the plays
    if n % 2 == 0:
        # If the number of plays is even, a tie is possible
        if player_wins['A'] <= n // 2 and player_wins['B'] <= n // 2:
            return '?'
        # If one player has won more than half of the plays, they are the winner
        else:
            return max(player_wins, key=player_wins.get)
    else:
        # If the number of plays is odd, the player with more wins is the winner
        return max(player_wins, key=player_wins.get)

