import collections

def solve():
    def check_winner(plays, x, y):
        sets = collections.defaultdict(int)
        current_set = 0
        current_winner = None
        for play in plays:
            if play == 'A':
                if current_winner is None:
                    current_set += 1
                sets[current_set] += 1
                if sets[current_set] == x:
                    winner = 'A'
                    break
                if sets[current_set] > y:
                    return winner
            else:
                if current_winner is None:
                    current_winner = 'B'
                sets[current_set] -= 1
                if sets[current_set] == 0:
                    current_set -= 1
                    if current_set == -1:
                        current_winner = None
                        current_set = 0
        if current_winner is None:
            return '?'
        if sets[current_set] > y:
            return current_winner
        winner = 'B' if current_winner == 'B' else 'A'
        for set_num in sets:
            if sets[set_num] > y:
                return winner
        return '?'

    t = int(input())
    for _ in range(t):
        n = int(input())
        plays = list(input())
        winner = check_winner(plays, n + 1, n + 1)
        print(winner)

import functools

def solve():
    @functools.lru_cache(maxsize=None)
    def twosort(arr, m):
        if not arr:
            return arr
        if m == 0:
            return sorted(arr)
        half = 2**(m-1)
        left, right = arr[:half], arr[half:]
        left = twosort(left, m-1)
        right = twosort(right, m-1)
        i = j = k = 0
        result = []
        while i < len(left) and j < len(right):
            if left[i] < right[j]:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1
        result.extend(left[i:])
        result.extend(right[j:])
        for _ in range(half):
            result[2*_] -= 1
        return result

    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        if twosort(arr, int(n.bit_length())-1) == sorted(arr):
            print("YES")
        else:
            print("NO")

import functools
from typing import List

def sort_with_twos(arr: List[int]):
    @functools.lru_cache(maxsize=None)
    def dp(n, k):
        if n == 1:
            return 1 if k == 0 else 0
        if k == 0:
            return 0
        res = float('inf')
        for i in range(1, min(k + 1, n) + 1):
            res = min(res, dp(n - 2 ** i, k - 2 ** i))
        return res + 1

    n = len(arr)
    return any(dp(n, i) < n for i in range(1, 1 << n))

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        print("YES" if sort_with_twos(arr) else "NO")

import functools
from typing import List

def solve():
    @functools.lru_cache(maxsize=None)
    def sort_array(a, m):
        if not a:
            return a
        if m == 0:
            return sorted(a)
        half = 2**(m - 1)
        return sort_array(a[:half], m - 1) + [a[i] - 1 for i in range(1, half + 1)] + sort_array(a[half:], m - 1)

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        result = "YES" if sort_array(a, int(math.log2(n)) + 1) == sorted(a) else "NO"
        print(result)

