def solve():
    @functools.lru_cache(maxsize=None)
    def sort_array(a, m):
        if not a:
            return a
        half = 2**m
        a[:half] = [max(0, x - 1) for x in a[:half]]
        return sort_array(a[half:], m - 1) + a[:half]

    def can_sort(a):
        return all(x <= y for x, y in zip(a, a[1:]))

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        if can_sort(a):
            print("YES")
        else:
            m = functools.reduce(max, a)
            while not can_sort(sort_array(a, m)):
                m -= 1
            print("YES") if can_sort(sort_array(a, m)) else print("NO")

