from typing import List

def solve():
    def twosort(arr):
        @functools.lru_cache(maxsize=None)
        def bit_mask(n):
            return [0] * n
            for i in range(n):
                bit_mask[i] = bit_mask[i | (i + 1)] + 1
            return bit_mask

        n = len(arr)
        bit_mask = bit_mask(n)
        for i in range(1, n):
            for j in range(i, n):
                if arr[i] > arr[j]:
                    m = bit_mask[j] - bit_mask[i]
                    arr[i ^ (1 << m)] -= 1
                    arr[j ^ (1 << m)] += 1

        return arr

    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        sorted_arr = twosort(arr)
        print("YES" if sorted_arr == sorted(arr) else "NO")

