import collections

def solve():
    def min_steps(pin):
        queue = collections.deque([(0, pin)])
        visited = set()
        while queue:
            pos, code = queue.popleft()
            if len(code) == 0:
                return pos
            current = int(code[pos])
            for i in [-1, 0, 1]:
                next_pos = pos + i
                if 0 <= next_pos < 4:
                    next_code = list(code)
                    next_code[pos] = next_code[next_pos]
                    next_code[next_pos] = current
                    if (next_pos, ''.join(next_code)) not in visited:
                        visited.add((next_pos, ''.join(next_code)))
                        queue.append((next_pos, next_code))
        return -1

    t = int(input())
    for _ in range(t):
        pin = input()
        print(min_steps(pin))

