        return (pos + 1) % 4 if pos < 3 else (pos - 3) % 4

    def press(pin, pos):
        return 1

    def enter(pin):
        visited = [0] * 4
        steps = 0
        pos = 1
        for digit in pin:
            while visited[pos] == 1:
                pos = move(pin, pos)
            visited[pos] = 1
            steps += press(pin, pos)
            pos = move(pin, pos)
        return steps

