def solve():
    def count_substrings(x, s):
        count = 0
        for i in range(len(x) - len(s) + 1):
            if x[i:i+len(s)] == s:
                count += 1
        return count

    def find_next_position(x, s):
        for i in range(len(x)):
            if x[i:] == s:
                return i
        return -1

    def append_x(x):
        return x + x

    def solve_helper(x, s):
        if find_next_position(x, s) != -1:
            return 0
        if count_substrings(x, s) > 0:
            return -1
        return 1 + min(solve_helper(append_x(x), s), solve_helper(x + s, s[1:]))

    t = int(input().strip())
    for _ in range(t):
        n, m = map(int, input().strip().split())
        x = input().strip()
        s = input().strip()
        print(solve_helper(x, s))

