from collections import defaultdict

def solve():
    def mex(arr):
        seen = defaultdict(int)
        for num in arr:
            seen[num] += 1
        for i in range(len(arr) + 1):
            if seen[i] == 0:
                return i
        return len(arr)

    def dp(n, k, x):
        dp = [[-1] * (x + 1) for _ in range(k + 1)]
        dp[0][0] = 0
        for i in range(1, k + 1):
            dp[i][0] = 0
        for i in range(1, n + 1):
            for j in range(1, min(i, k) + 1):
                for val in range(1, x + 1):
                    if dp[j - 1][val] != -1:
                        dp[i][j] = max(dp[i][j], dp[i - 1][val] + val)
                    mex_val = mex([val] + list(dp[i - 1][:j]))
                    if mex_val <= k and dp[i - 1][mex_val] != -1:
                        dp[i][j] = max(dp[i][j], dp[i - 1][mex_val] + mex_val)
        return dp[n][k] if dp[n][k] != -1 else -1

