def solve():
    @lru_cache(maxsize=None)
    def dp(n, k, x, used):
        if n == 0:
            return 0
        if k == 0:
            return -1
        if x == 0:
            return -1
        if (n, k, x) in used:
            return used[(n, k, x)]
        res = -1
        for i in range(1, min(k + 1, x + 1)):
            res = max(res, i + dp(n - 1, k, x - i, used))
        used[(n, k, x)] = res
        return res

    t = int(input())
    for _ in range(t):
        n, k, x = map(int, input().split())
        print(dp(n, k, x, {}))

