def solve():
    @functools.lru_cache(maxsize=None)
    def dfs(n, k, x, current_sum, current_set):
        if n == 0:
            return current_sum
        max_sum = -1
        for i in range(min(k, x + 1), 0, -1):
            if i not in current_set:
                new_current_set = current_set.union({i})
                max_sum = max(max_sum, dfs(n - 1, k, x, current_sum + i, new_current_set))
        return max_sum

