    def min_ops(arr):
        negatives = [x for x in arr if x < 0]
        positives = [x for x in arr if x > 0]
        if not negatives and not positives:
            return 0
        if not negatives:
            return len(positives)
        if not positives:
            return len(negatives) + 1
        return min(len(negatives) + min_ops(positives), len(positives) + min_ops(negatives)) + 1

