        subscribers = set(range(1, n+1))
        online_queue = deque(online)
        for _ in range(q):
            event = online_queue.popleft()
            if event == '+':
                online.add(online_queue.popleft())
            else:
                online.remove(event)
            if len(online) == a:
                return True
            if len(online) > a:
                return False
            if len(subscribers) - len(online) < n - a:
                return False
        return len(online) == n

    t = int(input())
    for _ in range(t):
        n, a, q = map(int, input().split())
        online = deque(range(1, a+1))
        result = 'YES' if check_online(n, a, q, online) else 'NO'
        if n - a > a:
            result = 'MAYBE'
        print(result)

