def solve():
    def is_valid(a, b):
        if len(a) != len(b) + 1:
            return False
        for i in range(1, len(a)):
            if a[i - 1] > a[i]:
                continue
            if a[i] < b[i - 1]:
                return False
        return True

    def find_sequence(b):
        n = len(b)
        m = n + 1
        while m <= 2 * n:
            a = [0] * m
            for i in range(n):
                if b[i] < a[i]:
                    a[i + 1] = b[i]
            if is_valid(a, b):
                return a
            m += 1
        return None

    for _ in range(int(input())):
        n = int(input())
        b = list(map(int, input().split()))
        sequence = find_sequence(b)
        if sequence is not None:
            print(len(sequence))
            print(*sequence)

