def solve():
    def is_valid(a: List[int], b: List[int]):
        if len(a) != len(b) + 2:
            return False
        a_i = a[1:]
        for i in range(1, len(a)):
            if a_i[i - 1] > a_i[i]:
                continue
            return False
        return True

    def generate_sequence(n: int, b: List[int]):
        a = [0] * (2 * n)
        a[0] = b[0]
        for i in range(1, n):
            if b[i - 1] > b[i]:
                continue
            a[i + 1] = b[i]
        for i in range(n, len(a)):
            a[i] = a[i - n]
        return a

    t = int(input())
    for _ in range(t):
        n = int(input())
        b = list(map(int, input().split()))
        if not is_valid(generate_sequence(n, b), b):
            print("Invalid input")
            continue
        m = 2 * n
        print(m)
        print(list(generate_sequence(m, b)))

