def solve():
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def split(a, b, c):
        for i in range(len(a)):
            for j in range(len(b)):
                if gcd(a[i], b[j]) != 1:
                    return False
            for j in range(len(c)):
                if gcd(a[i], c[j]) == 1:
                    b.append(a[i])
                    a.pop(i)
                    i -= 1
                    break
        c += a
        return b, c

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        b, c = split(a, [], [])
        if not b and not c:
            print(-1)
        else:
            print(len(b), len(c))
            print(*b)
            print(*c)

