def solve():
    @functools.lru_cache(maxsize=None)
    def count_ops(arr):
        if len(arr) == 1:
            return 0 if arr[0] == 0 else 1
        n = len(arr)
        left = count_ops(arr[:n // 2])
        right = count_ops(arr[n // 2:])
        return left + right + 1 if arr[n // 2] > arr[n // 2 + 1] else min(left, right)

    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        print(count_ops(arr))

