import functools

def solve():
    @functools.lru_cache(maxsize=None)
    def max_down(arr, n):
        if n == 1:
            return 0 if arr[0] == 0 else 1
        count = 0
        for i in range(1, n):
            if arr[i] < arr[i - 1]:
                count += max_down(arr, i)
                arr[i] = max(0, arr[i] - 1)
        return count + max_down(arr, n - 1) if arr[-1] != 0 else count

    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        print(max_down(arr, n))

