import itertools

def solve():
    n = int(input())
    students = list(map(int, input().split()))
    permutation = list(range(1, n+1))

    # Find the index of the first student that is not in the correct position
    for i in range(n):
        if students[i] != permutation[i]:
            break

    # Swap the student with the correct position and the student found above
    students[i], permutation[i] = permutation[i], students[i]

    # Swap the students in pairs until all students are in the correct position
    for operation in itertools.islice(itertools.permutations(range(n)), n//2):
        for i in range(n):
            if students[i] != permutation[i]:
                students[i], students[i + operation[i]] = students[i + operation[i]], students[i]
                permutation[i], permutation[i + operation[i]] = permutation[i + operation[i]], permutation[i]

    print(len(list(filter(lambda x: x != x[0], enumerate(zip(students, permutation))))))

import itertools

def solve():
    n = int(input())
    students = list(map(int, input().split()))
    permutation = list(range(1, n+1))

    # Find the index of the first student that is not in the correct position
    for i in range(n):
        if students[i] != permutation[i]:
            break

    # Swap the student with the correct position and the student found above
    students[i], permutation[i] = permutation[i], students[i]

    # Swap the students in pairs until they are all in the correct position
    for pair in itertools.pairwise(students):
        if pair[0] != pair[1]:
            students[pair.index0], students[pair.index1] = students[pair.index1], students[pair.index0]

    print(len(list(filter(lambda x: x != x[0], enumerate(students)))))

