def solve():
    def is_sorted(arr: List[int]):
        for i in range(1, len(arr)):
            if arr[i] < arr[i - 1]:
                return False
        return True

    def min_ops(arr: List[int]):
        n = len(arr)
        if is_sorted(arr):
            return 0
        ops = float('inf')
        for i in range(1, n):
            left_sum = sum(arr[:i])
            right_sum = sum(arr[i:])
            diff = left_sum - right_sum + 1
            ops = min(ops, diff)
            arr[i] += diff
            arr[i + 1:] = [x - diff for x in arr[i + 1:]]
        return ops

    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        print(min_ops(arr))

