    def min_ops(arr, n, i):
        if i == n:
            return 0
        if arr[i] > arr[i + 1]:
            return float('inf')
        min_val = float('inf')
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                min_val = min(min_val, 1 + min_ops(arr, n, j))
        if min_val == float('inf'):
            return 1 + min_ops(arr[:i] + [arr[i] + 1] + arr[i + 1:], n, i + 1)
        return 1 + min_val

