        for i in range(1, len(arr)):
            if arr[i] < arr[i - 1]:
                return False
        return True

    def min_ops(arr: List[int]):
        n = len(arr)
        if n == 1:
            return 0
        if is_sorted(arr):
            return 1
        min_ops_list = [0] * n
        for i in range(1, n):
            min_ops_list[i] = min_ops_list[i - 1] + 1
            if arr[i] > arr[i - 1]:
                min_ops_list[i] = min(min_ops_list[i], min_ops(arr[:i] + [arr[i] - 1] + arr[i + 1:]))
            if arr[i] < arr[i - 1]:
                min_ops_list[i] = min(min_ops_list[i], min_ops(arr[:i] + [arr[i] + 1] + arr[i + 1:]))
        return min_ops_list[-1]

