def solve():
    def max_layers(bread, cheese, ham):
        # Base cases for 0 slices of bread, cheese, or ham
        if not bread or not cheese and not ham:
            return 0
        if not bread:
            return max(max_layers(cheese, ham, 0), max_layers(0, cheese, ham))
        if not cheese and not ham:
            return 1

        # Recursive cases for each slice of cheese or ham
        max_layers_with_cheese = max_layers(bread - 2, cheese - 1, ham)
        max_layers_with_ham = max_layers(bread - 2, cheese, ham - 1)

        # Return the maximum number of layers between the two recursive cases
        return max(max_layers_with_cheese, max_layers_with_ham)

    # Read the number of test cases
    t = int(input())

    # Iterate through the test cases
    for _ in range(t):
        b, c, h = map(int, input().split())
        print(max_layers(b, c, h))

