        for i in range(1, n + 1):
            dp[i] = dp[i - 1] + abs(a[i] - a[i - 1])
        groups = []
        total = float('inf')
        for i in range(1, n):
            for j in range(i + 1, n):
                if len(groups) < k - 1:
                    groups.append((i, j))
                    new_dp = [0] * (n + 1)
                    for l in range(1, n + 1):
                        if l < i:
                            new_dp[l] = dp[l]
                        elif l > j:
                            new_dp[l] = dp[l]
                        else:
                            new_dp[l] = dp[i - 1] + dp[j + 1] - dp[l]
                    total = min(total, sum(new_dp[i + 1: j + 1]) + dp[j + 1])
        print(total)

