    for _ in range(t):
        n, k = map(int, input().split())
        a = list(map(int, input().split()))
        a.insert(0, 0)
        a.append(math.inf)
        @functools.lru_cache(maxsize=None)
        def f(i, j):
            if i == j:
                return 0
            return sum(abs(a[i] - a[i + 1]) for i in range(i, j))

        @functools.lru_cache(maxsize=None)
        def dp(i, k):
            if i == k:
                return 0
            res = math.inf
            for j in range(i + 1, n):
                res = min(res, dp(j, k) + f(i, j))
            return res + f(i, n)

        print(dp(1, k))

