def solve():
    def min_cuts(heights: List[int], lengths: List[int]) -> int:
        dp = [0] * (max(heights) + 1)
        for height, length in zip(heights, lengths):
            for i in range(height, 0, -1):
                dp[i] = max(dp[i], dp[i - height] + length)
        return max(dp)

    def read_input() -> List[List[int]]:
        n_tests = int(input())
        tests = []
        for _ in range(n_tests):
            n = int(input())
            heights = [int(x) for x in input().split()]
            lengths = [int(x) for x in input().split()]
            tests.append((heights, lengths))
        return tests

    tests = read_input()
    for test in tests:
        print(min_cuts(*test))

