def solve():
    def can_sum(target, numbers, exclude):
        memo = {0: set([[]])}
        for i in range(1, target + 1):
            if i in memo:
                continue
            for num in numbers:
                if num != exclude and i - num in memo:
                    memo[i] = memo[i - num] | {num + combination for combination in memo[i - num]}
        return memo[target] if target in memo else None

    t = int(input())
    for _ in range(t):
        n, k, x = map(int, input().split())
        numbers = set(range(1, k + 1)) - {x}
        combinations = can_sum(n, numbers, x)
        if combinations:
            print("YES")
            print(len(combinations))
            for combination in combinations:
                print(*combination)
        else:
            print("NO")

