def solve():
    def play_game(tsondu, tenzing):
        tsondu_monsters, tenzing_monsters = tsondu, tenzing
        while tsondu_monsters and tenzing_monsters:
            tsondu_monster, tenzing_monster = heapq.heappop(tsondu_monsters), heapq.heappop(tenzing_monsters)
            diff = abs(tsondu_monster - tenzing_monster)
            if diff <= 0:
                continue
            tsondu_monster -= tenzing_monster
            tenzing_monster -= tsondu_monster
            if tsondu_monster <= 0:
                tsondu_monsters.append(tsondu_monster)
            if tenzing_monster <= 0:
                tenzing_monsters.append(tenzing_monster)
        return bool(tsondu_monsters)

    def optimal_strategy(abilities):
        abilities.sort(reverse=True)
        return abilities

    def read_input():
        t_cases = int(input())
        for _ in range(t_cases):
            n, m = map(int, input().split())
            tsondu_abilities = list(map(int, input().split()))
            tenzing_abilities = list(map(int, input().split()))
            tsondu_abilities = optimal_strategy(tsondu_abilities)
            tenzing_abilities = optimal_strategy(tenzing_abilities)
            winner = "Tsondu" if play_game(tsondu_abilities, tenzing_abilities) else "Tenzing"
            print(winner)

    read_input()

