def solve():
    def fight(a, b):
        if a > b:
            return a - b, b - a
        else:
            return b - a, a - b

    def optimal_move(player, monsters):
        monsters.sort(reverse=True)
        opponent_monsters = opponent_monsters[::-1]
        result = []
        while monsters and opponent_monsters:
            a, b = monsters.pop(0), opponent_monsters.pop(0)
            x, y = fight(a, b)
            result.append(x)
            if y <= 0:
                opponent_monsters = opponent_monsters[::-1]
            else:
                monsters = [z for z in monsters if z > y]
        return result

    def game_result(player_monsters, opponent_monsters):
        if not player_monsters:
            return "Tenzing"
        if not opponent_monsters:
            return "Tsondu"
        player_moves = optimal_move(player_monsters, opponent_monsters)
        opponent_moves = optimal_move(opponent_monsters, player_monsters)
        if sum(player_moves) > sum(opponent_moves):
            return "Tsondu"
        elif sum(player_moves) < sum(opponent_moves):
            return "Tenzing"
        else:
            return "Draw"

    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        tsondu_monsters = list(map(int, input().split()))
        tenzing_monsters = list(map(int, input().split()))
        print(game_result(tsondu_monsters, tenzing_monsters))

import heapq

def solve():
    def play_game(tsondu, tenzing):
        while tsondu and tenzing:
            tsondu_max, tsondu_min = max(tsondu, key=lambda x: x[0]), min(tsondu, key=lambda x: x[0])
            tenzing_max, tenzing_min = max(tenzing, key=lambda x: x[0]), min(tenzing, key=lambda x: x[0])
            if tsondu_max > tenzing_min:
                tsondu.remove((tsondu_max[1], tsondu_max))
                tenzing.remove((tenzing_min[1], tenzing_min))
            elif tsondu_max < tenzing_min:
                tenzing.remove((tenzing_min[1], tenzing_min))
                tsondu.remove((tsondu_max[1], tsondu_max))
            else:
                tsondu.remove((tsondu_max[1], tsondu_max))
                tenzing.remove((tenzing_min[1], tenzing_min))
        return bool(tsondu)

    def main():
        t = int(input().strip())
        for _ in range(t):
            n, m = map(int, input().strip().split())
            tsondu = [(a, i) for i, a in enumerate(list(map(int, input().strip().split())))]
            tenzing = [(b, i) for i, b in enumerate(list(map(int, input().strip().split())))]
            heapq.nlargest(n, tsondu, key=lambda x: x[0])
            heapq.nsmallest(m, tenzing, key=lambda x: x[0])
            print("Tsondu" if play_game(tsondu, tenzing) else "Tenzing")
            print()

    main()

