def solve():
    def game(board):
        if len(board) == 1:
            return "Alice" if board[0] % 2 == 0 else "Bob"

        for i in range(1, len(board)):
            if board[i] == board[0]:
                board[i] = board[0] + board[i]
                board.remove(board[0])
                if game(board) == "Alice":
                    return "Alice"
                board[i] = board[0] - board[i]
                board.insert(i, board[0])

        return "Bob"

