from functools import lru_cache

@lru_cache(maxsize=None)
def min_moves(board, moves):
    if not moves:
        return 1 if len(board) == 1 else 0
    min_val = float('inf')
    for i in range(len(board)):
        if board[i] == moves[0]:
            new_board, new_moves = update_board(board, moves[0], i, moves[1:])
            min_val = min(min_val, min_moves(new_board, new_moves))
    return min_val

def update_board(board, value, index, remaining_values):
    new_board = list(board)
    new_board[index] = sum(remaining_values)
    new_moves = list(remaining_values)
    new_moves.sort(reverse=True)
    return new_board, new_moves

