def solve():
    for _ in range(int(input())):
        n = int(input())
        board = [1] * n
        counter = Counter(board)
        while counter:
            max_count = max(counter.values())
            for key in counter.keys():
                if counter[key] == max_count:
                    board = [x if x != key else 0 for x in board]
                    counter = Counter(board)
                    if not counter:
                        print("Alice")
                        break
                    if not max_count * (n - counter.most_common(1)[0][1]) in board:
                        print("Bob")
                        break
    return

