            return 0
        res = 0
        for i in range(1, min(remaining, len(board))):
            if board[i] == board[i - 1]:
                res += dp(remaining - i, board[:i] + [board[i] + board[i - 1]] + board[i + 1:])
        return res

    t = int(input())
    for _ in range(t):
        n = int(input())
        board = list(map(int, [1] * n))
        if dp(n, board) == 0:
            print("Bob")
        else:
            print("Alice")

