import math

def solve():
    def good_array(n, k, ones):
        return all(ones[:i] >= math.ceil(i / k) and ones[-i:] >= math.ceil(i / k) for i in range(1, n + 1))

    def min_ones(n, k):
        if k == 1:
            return n
        if k > n:
            return 0
        if k == n:
            return 1
        if k == 2:
            return n // 2
        left, right = 0, n
        while left < right:
            mid = (left + right) // 2
            if good_array(n, k, [1] * mid + [0] * (n - mid)):
                right = mid
            else:
                left = mid + 1
        return left

    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        print(min_ones(n, k))

