import math

def solve():
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def extended_euclidean(a, b):
        if not b:
            return (1, 0, a)
        else:
            g, x1, y1 = extended_euclidean(b, a % b)
            x = y1 - (a // b) * x1
            return (g, x, y1)

    def find_initial_numbers(numbers):
        n = len(numbers)
        if n < 3:
            return None

        # Calculate the GCD of all pairs of numbers
        gcds = [(gcd(numbers[i], numbers[j])) for i in range(n) for j in range(i + 1, n)]

        # Find the greatest common divisor of all GCDs
        gcd_gcd = max(gcds)

        # Find the pair of numbers that produce the GCD_GCD when their difference is taken
        for i in range(n):
            for j in range(i + 1, n):
                if gcd_gcd == gcd(numbers[i], numbers[j]):
                    return numbers[i], numbers[j]

        # If no such pair is found, return None
        return None

    test_cases = int(input())
    for _ in range(test_cases):
        n = int(input())
        numbers = list(map(int, input().split()))
        initial_numbers = find_initial_numbers(numbers)
        if initial_numbers:
            print(initial_numbers[0])
        else:
            print("No solution")

