def solve():
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def extended_euclidean_algorithm(a, b):
        if b == 0:
            return (1, 0, a)
        else:
            g, y, x = extended_euclidean_algorithm(b, a % b)
            return (x - (a // b) * g, g, y)

    def find_gcd(nums):
        gcd_val = math.gcd(*nums)
        gcd_pair = extended_euclidean_algorithm(gcd_val, sum(nums))
        return gcd_pair[1], gcd_pair[2]

    @functools.lru_cache(maxsize=None)
    def get_diff_count(num, diff_set):
        count = 0
        for diff in diff_set:
            if num % diff == 0:
                count += num // diff
        return count

    def find_initial_numbers(nums):
        gcd, x, y = find_gcd(nums)
        diff_set = set()
        for i in range(1, gcd + 1):
            diff_set.add(i)
            diff_count = get_diff_count(i, diff_set)
            if diff_count > len(nums) // 2:
                diff_set.remove(i)
        return nums[x], nums[y]

    t = int(input())
    for _ in range(t):
        n = int(input())
        nums = list(map(int, input().split()))
        initial_numbers = find_initial_numbers(nums)
        print(*initial_numbers)

