def solve():
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def extended_euclidean_algorithm(a, b):
        if a == 0:
            return (0, 1, b)
        else:
            g, x1, y1 = extended_euclidean_algorithm(b % a, a)
            x = y1 - (b // a) * x1
            y = 1 - (b // a) * x1
            return (g, x, y)

    def find_gcd(nums):
        gcd_values = defaultdict(int)
        for num in nums:
            gcd_values[gcd(num, gcd_values[num])] += 1
        return max(gcd_values.keys())

    def find_initial_numbers(nums):
        g = find_gcd(nums)
        x, y, _ = extended_euclidean_algorithm(g, len(nums))
        return nums[x], nums[x + y]

    t = int(input().strip())
    for _ in range(t):
        n = int(input().strip())
        nums = list(map(int, input().strip().split()))
        initial_numbers = find_initial_numbers(nums)
        print(initial_numbers[0])

