def solve():
    def is_good(a):
        return sum(a) >= 0 and math.gcd(*a) == 1

    def flip(a, i):
        a[i] *= -1

    def min_flips(a):
        n = len(a)
        dp = [[0] * 2 for _ in range(n)]
        for i in range(n):
            for j in range(i):
                if a[i] * a[j] == -1:
                    dp[i][1] = max(dp[j][0] + 1, dp[i][1])
                else:
                    dp[i][0] = max(dp[j][0], dp[i][0])
            dp[i][0] = max(dp[i][0], dp[i][1])
        return dp[n - 1][0]

    t = int(input())
