            flips = min_flips(a)
            if is_good(a):
                print(0)
            else:
                flips += 1
                flip(a, 0)
                if is_good(a):
                    print(flips)
                else:
                    for i in range(1, n):
                        if a[i] == -1:
                            flip(a, i)
                            if is_good(a):
