def solve():
    def product(arr):
        prod = 1
        for num in arr:
            prod *= num
        return prod

    def sum_abs(arr):
        sum = 0
        for num in arr:
            sum += abs(num)
        return sum

    def min_ops(arr):
        n = len(arr)
        if n == 1:
            return 0 if arr[0] == 1 else 1
        if sum_abs(arr) <= 1 or product(arr) == 1:
            return 0
        min_ops_count = float('inf')
        for i in range(n):
            if arr[i] == -1:
                arr[i] = 1
                new_product = product(arr)
                new_sum = sum_abs(arr)
                if new_product == 1 and new_sum >= 0:
                    min_ops_count = min(min_ops_count, 1 + min_ops(arr))
                arr[i] = -1
                new_product = product(arr)
                new_sum = sum_abs(arr)
                if new_product == 1 and new_sum >= 0:
                    min_ops_count = min(min_ops_count, 1 + min_ops(arr))
        return min_ops_count

    t = int(input().strip())
