def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Check if all elements are positive
    if any(x < 0 for x in a):
        print("NO")
        return

    # Check if all elements have the same parity
    parity = a[0] % 2
    if any(x % 2 != parity for x in a[1:]):
        print("NO")
        return

    # Check if it's possible to build a beautiful array
    @functools.lru_cache(maxsize=None)
    def can_build(remaining, target_parity):
        if not remaining:
            return target_parity == 0
        if remaining[0] % 2 != target_parity:
            return False
        return any(can_build(remaining[i:], target_parity) for i in range(1, len(remaining))) or any(can_build(remaining[i:], 1 - target_parity) for i in range(1, len(remaining)))

    if can_build(a, parity):
        print("YES")
    else:
        print("NO")

