def solve():
    def dfs(books, skills, minutes, dp):
        if not books:
            return float('inf') if skills != (1, 1) else 0
        min_time = float('inf')
        for book, skill in zip(books[0], skills):
            if skill:
                new_skills = (skills[0] | (1 << book), skills[1])
                new_minutes = minutes + books[0][book]
