def solve():
    def dfs(books, skills, time, dp):
        if not books:
            return float('inf') if skills != (1, 1) else 0
        min_time = float('inf')
        for i, (m, s) in enumerate(books):
            new_skills = (skills[0] | s[0], skills[1] | s[1])
            new_time = time + m
            if new_skills == (1, 1):
                min_time = min(min_time, new_time)
            if dp[new_skills] == -1:
                dp[new_skills] = dfs(books[i+1:], new_skills, new_time, dp)
            min_time = min(min_time, dp[new_skills] if dp[new_skills] != -1 else float('inf'))
        dp[skills] = min_time
        return dp[skills]

    return lambda: dfs([(m, s) for m, s in zip(map(int, input().split()), map(int, input().split()))], (0, 0), 0, {(0, 0): -1})

