def solve():
    @functools.lru_cache(maxsize=None)
    def divisors(n):
        divisors = []
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divisors.append(i)
                divisors.append(n // i)
        divisors.sort()
        return divisors

    def perfect_array(n):
        divisors = divisors(n)
        result = [0] * n
        for i in range(1, n + 1):
            result[i - 1] = divisors[i - 1]
        total = sum(result)
        while total % n != 0:
            next_divisor = divisors[n - total % n]
            for j in range(1, n):
                if result[j] == next_divisor:
                    result[j] += next_divisor
                    total += next_divisor
                    break
        return result

    t = int(input())
    for _ in range(t):
        n = int(input())
        print(*perfect_array(n))

