def solve():
    n, k = map(int, input().split())
    members = [list(input()) for _ in range(n)]

    def count_agree(members, opinion):
        return sum(1 for member in members if member[opinion] == '+')

    def count_disagree(members, opinion):
        return sum(1 for member in members if member[opinion] == '-')

    max_members = 1
    for i in range(1, n):
        for expulsions in itertools.combinations(range(1, n), i):
            remaining_members = [members[j] for j in range(1, n) if j not in expulsions]
            for opinion in range(k):
                if count_agree(remaining_members, opinion) > count_disagree(remaining_members, opinion):
                    break
            else:
                max_members = max(max_members, len(remaining_members))

    print(max_members + 1)

import itertools

def solve():
    def count_agree(members, opinions):
        return sum(1 for member, opinion in zip(members, opinions) if member == opinion)

    def max_members(n, k, members, opinions):
        max_members = 1
        for i in range(1, n):
            for expel in range(i):
                for subset in itertools.combinations(range(1, n), expel):
                    new_members = list(set(members) - set(subset))
                    new_opinions = [opinions[i] for i in new_members]
                    if count_agree(new_members, new_opinions) > count_agree(new_members, [opinions[i] for i in subset]):
                        new_members.append(subset[0])
                    else:
                        new_members += subset
                    if len(new_members) > max_members:
                        max_members = len(new_members)
        return max_members + 1

    t = int(input())
