def dijkstra(start, end, grid):
    distances = {start: 0}
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current = heapq.heappop(priority_queue)

        if current == end:
            return distances[end]

        for neighbor in [(current[0] + 1, (current[1], current[0] + 1)),
                         (current[0] - 1, (current[1], current[0] - 1)),
                         (current[1] + 1, (current[0], current[1] + 1)),
                         (current[1] - 1, (current[0], current[1] - 1))]:
            if neighbor[0] > 2 or not (0 <= neighbor[1][0] < 10**9 and 0 <= neighbor[1][1] < 10**9):
                continue

            new_distance = current_distance + 1
            if neighbor[1] not in distances or new_distance < distances[neighbor[1]]:
                distances[neighbor[1]] = new_distance
                heapq.heappush(priority_queue, (new_distance, neighbor[1]))

    return -1

