import heapq

def manhattan_distance(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def dijkstra(start, end, grid):
    distances = {start: 0}
    neighbors = []
    heapq.heappush(neighbors, (0, start))

    while neighbors:
        current_distance, current = heapq.heappop(neighbors)
        if current in distances:
            continue
        distances[current] = current_distance

        for neighbor in [(current[0] + 2 * dx, current[1] + 2 * dy) for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]]:
            if 0 <= neighbor[0] < 10 ** 9 and 0 <= neighbor[1] < 10 ** 9 and neighbor not in distances and manhattan_distance(neighbor, end) <= 2:
                heapq.heappush(neighbors, (current_distance + 1, neighbor))

    return distances[end]

