import math

def solve():
    def spell(x, spell_type):
        if spell_type == 1:
            return 2 * x - 1
        else:
            return 2 * x + 1

    def binary_search(n, spells):
        left, right = 0, spells
        while left <= right:
            mid = (left + right) // 2
            candies = spells[mid]
            if candies >= n:
                right = mid - 1
                best_spells = spells[:mid]
            else:
                left = mid + 1
        return best_spells

    def solve_helper(n, spells_used):
        if spells_used == 40:
            return [n] if n == 1 else -1
        candies = 1
        spells = []
        for _ in range(spells_used):
            if candies < n:
                spells.append(1)
                candies = spell(candies, 1)
            elif candies > n:
                spells.append(2)
                candies = spell(candies, 2)
            else:
                return spells + solve_helper(n, spells_used + 1)
        return spells + solve_helper(n, spells_used + 1)

    t = int(input())
    for _ in range(t):
        n = int(input())
        spells = list(range(1, 41))
        spells = binary_search(n, spells)
        if spells:
            print(len(spells))
            print(*spells)
        else:
            print(-1)

