from collections import deque

def solve():
    n = int(input())
    if n == 1:
        return 1, [1]

    q = deque([(1, [1])])
    visited = set()
    while q:
        candies, steps = q.popleft()
        if candies == n:
            return len(steps), steps

        if (candies, len(steps)) in visited:
            continue
        visited.add((candies, len(steps)))

        if candies > n:
            continue

        q.append((2 * candies + 1, steps + [2]))
        q.append((2 * candies - 1, steps + [1]))

    return -1

