def solve():
    t = int(input())
    for _ in range(t):
        s = input()
        if len(set(s)) < 4:
            print(-1)
        else:
            count = Counter(s)
            bulbs = list(range(4))
            operations = 0
            while True:
                if count[s[bulbs[0]]] == 0:
                    count[s[bulbs[0]]] += 1
                    operations += 1
                    bulbs[0] = (bulbs[0] + 1) % 4
                else:
                    count[s[bulbs[0]]] -= 1
                    operations += 1
                    if all(count[s[i]] == 0 for i in bulbs):
                        break
            print(operations)

