            print(-1)
        else:
            # Find the number of unique colors
            unique_colors = len(set(s))
            # Find the number of pairs of same-colored bulbs
            pairs = sum(1 for i in range(4) for j in range(i+1, 4): 1 if s[i] == s[j])
            # If there are more than 2 pairs, it's impossible to turn all bulbs on
            if pairs > 2:
                print(-1)
            else:
                # Find the number of bulbs that are off
                off_bulbs = sum(1 for i in range(4) if s[i] == 0)
                # If there are an odd number of off bulbs, it's impossible to turn all bulbs on
                if off_bulbs % 2 != 0:
                    print(-1)
                else:
                    # Calculate the number of operations
                    operations = off_bulbs // 2 + pairs
                    print(operations)

