def solve():
    def is_reachable(a, b, c, d):
        if a > c and b > d:
            return False
        if a < c and b < d:
            return False
        if abs(a - c) + abs(b - d) == 2:
            return True
        return False

    def min_steps(a, b, c, d):
        steps = 0
        while (a != c or b != d):
            if a > c:
                a -= 1
            elif b > d:
                b -= 1
            else:
                a += 1
                b += 1
            steps += 1
        return steps

    t = int(input())
    for _ in range(t):
        a, b, c, d = map(int, input().split())
        if is_reachable(a, b, c, d):
            print(min_steps(a, b, c, d))
        else:
            print(-1)

