import heapq

def bfs(board, start, end):
    queue = [(0, start)]
    visited = set()
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        sec, (r, c) = heapq.heappop(queue)
        if (r, c) == end:
            return sec
        if (r, c) in visited:
            continue
        visited.add((r, c))
        for dr, dc in directions:
            new_r, new_c = r + dr, c + dc
            if 0 <= new_r < 201 and 0 <= new_c < 201:
                heapq.heappush(queue, (sec + 1, (new_r, new_c)))

    return -1

