            sec, path = heapq.heappop(q)
            if path[-1] == (a, b):
                return sec
            for dx, dy in directions:
                x, y = path[-1]
                nx, ny = x + dx, y + dy
                if 0 <= nx < R and 0 <= ny < C and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    heapq.heappush(q, (sec + 1, path + [(nx, ny)]))

    for sec, path in enumerate(bfs() for a, b in map(int, input().split())):
        print(sec)

