    moves = [(0, 0), (0, 1), (0, -1), (1, 0), (-1, 0)]

    while q:
        r, c, steps = heapq.heappop(q)

        for dr, dc in moves:
            new_r, new_c = r + dr, c + dc
            if new_r < 0 or new_r >= R or new_c < 0 or new_c >= C:
