    while queue:
        seconds, current = heapq.heappop(queue)

        if current == end:
            return seconds

        if current in visited:
            continue

        visited.add(current)

        for dx, dy in directions:
            next_cell = (current[0] + dy, current[1] + dx)
            if -100 < next_cell[0] < 101 and -100 < next_cell[1] < 101:
                heapq.heappush(queue, (seconds + 1, next_cell))

