import itertools

def solve():
    @functools.lru_cache(maxsize=None)
    def dp_max(i, likes):
        if i == 0:
            return 0
        return max(likes[i] + dp_max(i - abs(likes[i]), likes), dp_max(i - 1, likes))

    @functools.lru_cache(maxsize=None)
    def dp_min(i, likes):
        if i == 0:
            return 0
        return min(likes[i] + dp_min(i - abs(likes[i]), likes), dp_min(i - 1, likes))

    def main():
        t = int(input())
        for _ in range(t):
            n = int(input())
            likes = list(map(int, input().split()))
            max_likes = [dp_max(i, likes) for i in range(1, n + 1)]
            min_likes = [dp_min(i, likes) for i in range(1, n + 1)]
            print(*max_likes)
            print(*min_likes)

    main()

