from collections import deque

def solve():
    n, m = map(int, input().split())
    actions = list(map(int, input().split()))
    recent_actions = deque([i for i in range(1, n + 1)])
    actions_queue = deque(actions)
    result = [-1] * n
    time = 0

    while actions_queue or recent_actions:
        if actions_queue:
            action = actions_queue.popleft()
            if action - 1 == recent_actions[0]:
                recent_actions.popleft()
            else:
                recent_actions.appendleft(action)
                recent_actions.popleft()
            time += 1
            result[action - 1] = time
        else:
            time_to_remove = float('inf')
            for i in range(n):
                if recent_actions[i] != recent_actions[0]:
                    time_to_remove = min(time_to_remove, time + 1)
                    break
            for _ in range(time_to_remove):
                recent_actions.popleft()
            time += time_to_remove

    print(*result)

