from collections import defaultdict
from heapq import heappush, heappop

def dijkstra(graph, start, end):
    distances = {start: 0}
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        if current_node == end:
            return current_distance

        if current_node in distances:
            continue

        distances[current_node] = current_distance

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight
            if neighbor not in distances or distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))

    return -1

def solve():
    t = int(input())

    for _ in range(t):
        n, m, x1, y1, x2, y2 = map(int, input().split())
        graph = defaultdict(lambda: {})

        for i in range(1, n):
            for j in range(1, m):
                graph[(i, j)][(i, j + 1)] = 1
                graph[(i, j)][(i + 1, j)] = 1

        obstacles = set()

        while True:
            obstacles_to_add = dijkstra(graph, (x1, y1), (x2, y2))
            if obstacles_to_add == -1:
                break

            obstacles.update(obstacles_to_add)
            for obstacle in obstacles_to_add:
                for neighbor, weight in graph[obstacle].items():
                    graph[obstacle].pop(neighbor, None)
                    if not graph[neighbor]:
                        del graph[neighbor]

        print(len(obstacles))

