        pool = tuple(iterable)
        n = len(pool)
        if r > n:
            return
        for i in range(r, n + 1):
            yield tuple(pool[j] for j in range(i))
        for r2 in range(1, r):
            for combination in combinations(pool, r2):
                for i in range(n - r + r2):
                    yield tuple(combination + (pool[i + r2],))

