def solve():
    def kill(monsters, health):
        heapq.heapify(monsters)
        while monsters:
            h1, h2 = heapq.heappop(monsters), heapq.heappop(monsters)
            if h1 > 0 and h2 > 0:
                heapq.heappush(monsters, h1 - 1, h2 - 1)
            else:
                if h1 > 0:
                    health[monsters.index(h1)] = 0
                if h2 > 0:
                    health[monsters.index(h2)] = 0
        return len(monsters)

