def solve():
    def move(x, y, direction):
        if direction == 'L':
            return x - 1, y
        elif direction == 'R':
            return x + 1, y
        elif direction == 'U':
            return x, y - 1
        elif direction == 'D':
            return x, y + 1
        else:
            raise ValueError("Invalid direction")

    def is_on_candy(x, y):
        return x == 1 and y == 1

    def is_valid_move(x, y, direction):
        if x < 0 or y < 0:
            return False
        return True

    def can_reach_candy(s):
        x, y = 0, 0
        for direction in s:
            x, y = move(x, y, direction)
            if is_on_candy(x, y):
                return True
            if not is_valid_move(x, y, direction):
                return False
        return False

    t = int(input())
    for _ in range(t):
        n = int(input())
        s = input()
        if can_reach_candy(s):
            print("YES")
        else:
            print("NO")

