def solve():
    def power(a, b, m):
        result = 1
        while b > 0:
            if b & 1:
                result = (result * a) % m
            a = (a * a) % m
            b >>= 1
        return result

    def extended_euclidean_algorithm(a, b):
        if b == 0:
            return (1, 0, a)
        else:
            g, y, x = extended_euclidean_algorithm(b, a % b)
            return (x - (a // b) * g, g, y)

    def chinese_remainder(n, a, b):
        p, g, x = n, 1, 0
        for i in range(len(b)):
            g, x = extended_euclidean_algorithm(p[i], b[i])
            x = (x * power(a[i], p[i] - p[i] // b[i] * g)) % p[i]
        return x % n

    def solve_for_n(n):
        factors = [i for i in range(2, int(n ** 0.5) + 1) if n % i == 0]
        if len(factors) == 0:
            return -1
        else:
            solutions = []
            for factor in factors:
                x = chinese_remainder([(n // factor, power(factor, factor - 1, factor - 1), 1), (factor, 1, 0)], [(1, 1, 0), (factor - 1, -power(factor, factor - 1, factor - 1), 1)])
                solutions.append((x % factor, factor))
            return min(solutions, key=lambda x: x[0]) if len(solutions) > 1 else solutions[0]

    t = int(input())
    for _ in range(t):
        n = int(input())
        x, y = solve_for_n(n)
        print(x, y)

