from collections import deque

def solve():
    n = int(input())
    deck = deque([0] * n)
    alice, bob = deque([0]), deque([0])

    while deck:
        step = len(deck)
        for _ in range(step):
            if step % 2 == 0:
                alice.append(deck.popleft())
            else:
                bob.append(deck.popleft() * step)

    print(*alice, *bob)

