def solve():
    def flip(arr, i):
        arr[i], arr[i+1] = arr[i+1], -arr[i]
        return arr

    def max_sum(arr):
        return max(reduce(lambda x, y: x + y, arr))

    def main():
        t = int(input())
        for _ in range(t):
            n = int(input())
            arr = list(map(int, input().split()))
