import heapq

def solve():
    n = int(input())
    towers = [list(map(int, input().split())) for _ in range(n)]

    # Initialize a min-heap with the number of blocks in each tower
    heap = [(-blocks, i) for i, blocks in enumerate(towers)]
    result = 0

    while heap:
        blocks, index = heapq.heappop(heap)
        if blocks > 0:
            result += blocks
            blocks -= 1
        else:
            blocks = -blocks
            for j in range(len(towers)):
                if towers[j] > 0 and towers[j] >= blocks:
                    towers[j] -= blocks
                    heapq.heappush(heap, (-towers[j], j))

    print(result)

