from typing import List

def solve():
    def area(points: List[List[int]]):
        x, y, s = 0, 0, 0
        for i in range(3):
            x += points[i][0]
            y += points[i][1]
            s += points[i][0] * points[(i + 1) % 3][1] - points[i][1] * points[(i + 1) % 3][0]
        return abs(s / 2)

    def cut_triangle(points: List[List[int]]):
        x1, y1, x2, y2 = points[0], points[1], points[2], points[0]
        if x1 == x2:
            return x1, y1, min(y1, y2), max(y1, y2)
        elif y1 == y2:
            return x1, min(x1, x2), y1, max(x1, x2)
        else:
            m = (y2 - y1) / (x2 - x1)
            return x1, y1, x1 + (y1 - y2) / m, y1

    def check_cut(points: List[List[int]], cut_point: List[int]):
        x1, y1, x2, y2 = points[0], points[1], points[2], points[0]
        if cut_point[0] == x1:
            return y1 <= cut_point[1] <= y2
        elif cut_point[1] == y1:
            return x1 <= cut_point[0] <= x2
        else:
            return abs((cut_point[1] - y1) / (cut_point[0] - x1) - (y2 - y1) / (x2 - x1)) < 1e-9

    def solve_case():
        n = int(input())
        for _ in range(n):
            points = []
            for _ in range(3):
                x, y = map(int, input().split())
                points.append([x, y])
            area_before = area(points)
            cut_point = cut_triangle(points)
            if check_cut(points, cut_point):
                area_after = area([points[0], cut_point, points[1]]) + area([points[2], cut_point, points[0]])
                if area_after > area_before:
                    print("YES")
                else:
                    print("NO")
            else:
                print("NO")

    solve_case()

