def solve():
    @functools.lru_cache(maxsize=None)
    def count_letters(word):
        counter = {}
        for letter in word:
            if letter in counter:
                counter[letter] += 1
            else:
                counter[letter] = 1
        return counter

    def can_print(word):
        n = len(word)
        if n % 2 == 1:
            return False
        counter = count_letters(word[:n//2])
        for letter in word[n//2:]:
            if letter in counter:
                counter[letter] += 1
            else:
                counter[letter] = 1
            if len(counter) > n//2:
                return False
        return True

    t = int(input())
    for _ in range(t):
        n = int(input())
        word = input()
        if can_print(word):
            print("YES")
        else:
            print("NO")

