from collections import defaultdict

def solve():
    def count_distinct(arr, start, end):
        counter = defaultdict(int)
        for i in range(start, end + 1):
            counter[arr[i]] += 1
        return len(counter)

    def max_gap(arr):
        n = len(arr)
        max_gap = 0
        for i in range(n):
            for j in range(i + 1, n):
                gap = j - i - count_distinct(arr, i, j)
                if gap > max_gap:
                    max_gap = gap
        return max_gap

    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        print(f"{max_gap(arr) + 1}, {max_gap(arr) + 1 + max_gap(arr[max_gap(arr) + 1:])}")

