def solve():
    def swap(a, i, j, b):
        a[i], a[j] = (a[j] ^ (1 << b)) | (a[i] & ~(1 << b)), (a[j] & ~(1 << b)) | (a[i] ^ (1 << b))

    def dfs(a, n, best, cur_min, cur_max):
        if n == 1:
            best[0] = max(best[0], cur_max - cur_min)
            return

        for i in range(n - 1):
            for j in range(i + 1, n):
                for b in range(32):
                    swap(a, i, j, b)
                    dfs(a, n - 1, best, min(cur_min, a[i]), max(cur_max, a[j]))
                    swap(a, i, j, b)

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        best = [0]
        dfs(a, n, best, float('inf'), -float('inf'))
        print(best[0])

