        a[i] ^= (1 << b)
        a[j] ^= (1 << b)

    def dfs(a, min_val, max_val, n):
        if n == 1:
            return max_val - min_val
        for i in range(n - 1):
            for j in range(i + 1, n):
                for b in range(32):
                    swap(a, i, j, b)
                    left = dfs(a, min(a), max(a), n // 2)
                    a[i], a[j] = a[j], a[i]
                    right = dfs(a, min(a), max(a), n // 2)
                    a[i], a[j] = a[j], a[i]
                    max_val = max(max_val, left + right)
        return max_val

