        return max(reduce(lambda x, y: max(x - y, y - x), arr[1:] + [arr[0] - arr[-1]]) if arr else 0

    def next_gap(arr, gap):
        return sorted(arr + [len(arr) + 1])[:gap + 1]

    def permute(arr, n):
        if n == 1:
            return [arr[0]]
        else:
            return [x for i in range(1, n) for x in permute(arr[1:] + [arr[0]], n - 1)] + [arr]

    def solve_helper(arr, n):
        if n == 1:
            return [arr[0]]
        else:
            max_gap = 0
            max_perm = None
            for i in range(1, n):
                gap = gap(arr[:i] + arr[i+1:])
                if gap > max_gap:
                    max_gap = gap
                    max_perm = next_gap(arr, gap)
            return max_perm

    return solve_helper(list(range(1, 1001)), 1000)

