def solve():
    def check_dialog(dialog):
        if len(dialog) == 1:
            return "Yes" if dialog[0] == "Q" else "No"

        last_question = dialog[0]
        answers = []
        for message in dialog[1:]:
            if message == "Q":
                if last_question == "A":
                    return "No"
                last_question = message
            else:
                answers.append(message)
                last_question = message

        if len(answers) == 0:
            return "No"
        for i in range(len(answers) - 1):
            if answers[i] == "A" and answers[i + 1] == "Q":
                return "No"
        return "Yes"

    t = int(input())
    for _ in range(t):
        n = int(input())
        dialog = list(input().strip())
        print(check_dialog(dialog))

