def is_valid_move(board, rook, new_pos):
    x, y = rook
    nx, ny = new_pos
    for i in range(x, nx + 1):
        if board[i][y] == 1:
            return False
    for j in range(y, ny + 1):
        if board[x][j] == 1:
            return False
    return True

def dfs(board, rooks, pos, moves):
    if len(moves) == 1:
        return True

    for new_pos in moves:
        if is_valid_move(board, rooks[pos], new_pos):
            board[rooks[pos][0]][rooks[pos][1]] = 0
            board[new_pos[0]][new_pos[1]] = 1
            rooks[pos] = new_pos
            if dfs(board, rooks, pos + 1, moves[1:]):
                return True
            board[rooks[pos][0]][rooks[pos][1]] = 1
            board[new_pos[0]][new_pos[1]] = 0

    return False

