    @functools.lru_cache(maxsize=None)
    def min_ops(arr, n):
        if n == 1:
            return 0 if arr[0] >= arr[1] else 1
        res = float('inf')
        for i in range(n - 1):
            res = min(res, min_ops(arr[:i] + arr[i + 1:], n - 1) + 1 if arr[i] > arr[i + 1] else res)
        return res

    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        print(min_ops(arr, n))

import heapq

def solve():
    def non_decreasing(a):
        n = len(a)
        if n == 1:
            return 0
        heap = a[:]
        heapq.heapify(heap)
        for i in range(1, n):
            if heap[i] < heap[i - 1]:
                return 1 + min(non_decreasing(a[:i] + a[i + 1:]))
        return 0

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        print(non_decreasing(a))

import functools
from typing import List

def solve():
    @functools.lru_cache(maxsize=None)
    def min_ops(arr, n):
        if n == 1:
            return 0 if arr[0] >= 0 else 1
        min_ops_count = float('inf')
        for i in range(n):
            if arr[i] < 0:
                for j in range(i+1, n):
                    if arr[j] >= 0:
                        new_arr = arr.copy()
                        new_arr[i] += new_arr[j]
                        del new_arr[j]
                        min_ops_count = min(min_ops_count, 1 + min_ops(new_arr, n-1))
        return min_ops_count

    while True:
        t = int(input())
        if not t:
            break
        n = int(input())
        arr = list(map(int, input().split()))
        print(min_ops(arr, n))

