def solve():
    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        a = list(map(int, input().split()))
        stack = []
        for i in range(n):
            if a[i] == 1:
                stack.append(1)
            while stack and stack[-1] == 0 and len(stack) + len(stack[-1:]) >= k:
                stack[-1] += len(stack)
                stack.pop()
        if len(stack) == 1 and stack[0] == 1:
            print("YES")
        else:
            print("NO")

