from typing import List

def solve():
    def add_to_even(arr, val):
        res = 0
        for i, num in enumerate(arr):
            if i & 1 == 0:
                arr[i] += val
                res += num
        return res

    def add_to_odd(arr, val):
        res = 0
        for i, num in enumerate(arr):
            if i & 1 == 1:
                arr[i] += val
                res += num
        return res

    n, q = map(int, input().split())
    arr = list(map(int, input().split()))
    for _ in range(q):
        query_type, val = map(int, input().split())
        if query_type == 0:
            print(add_to_even(arr, val))
        else:
            print(add_to_odd(arr, val))

from collections import defaultdict

def solve():
    n, q = map(int, input().split())
    a = list(map(int, input().split()))
    even_sum, odd_sum = 0, 0
    even_map, odd_map = defaultdict(int), defaultdict(int)

    for num in a:
        if num % 2 == 0:
            even_sum += num
            even_map[num] += 1
        else:
            odd_sum += num
            odd_map[num] += 1

    for _ in range(q):
        type_, x = map(int, input().split())
        if type_ == 0:
            for num in even_map:
                even_map[num] -= 1
                even_map[num + x * 2] += 1
            even_sum += x * 2 * len(even_map)
        else:
            for num in odd_map:
                odd_map[num] -= 1
                odd_map[num + x * 2 + 1] += 1
            odd_sum += x * 2 * len(odd_map)

    print(even_sum + odd_sum)

