import collections

def solve():
    def transform(arr, letter):
        result = []
        for num in arr:
            result.append(letter)
        return result

    def can_transform(arr, s):
        count = collections.Counter(arr)
        letters = set(s)
        for letter in letters:
            if letter not in count:
                return False
            while count[letter] > 0:
                index = s.find(letter)
                if index == -1:
                    break
                s = s[:index] + str(arr[count[letter]] + 1) + s[index + 1:]
                count[arr[count[letter]]] -= 1
                count[arr[count[letter] + 1] if count[letter] + 1 < len(arr) else len(arr)] += 1
        return s == ''.join(map(str, arr))

    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        s = input()
        print("YES" if can_transform(arr, s) else "NO")

import collections

def solve():
    def transform(arr, letters):
        while any(num > 0 for num in arr):
            num, letter = arr[0], letters[0]
            for i in range(len(arr)):
                if arr[i] == num:
                    arr[i] = letter
            arr.remove(num)
            letters.remove(letter)
        return ''.join(arr)

    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        s = input()
        letters = list(set(s))
        if len(letters) > len(set(arr)):
            print("NO")
        elif transform(arr, letters) == s:
            print("YES")
        else:
            print("NO")

