def solve():
    def transform(a, s):
        letters = set(s)
        for num in a:
            for letter in letters:
                a[:] = [letter if i == num else i for i in a]
                if s == ''.join(a):
                    return True
        return False

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        s = input()
        print("YES" if transform(a, s) else "NO")

import collections
import re

def solve():
    def transform(arr, letters):
        while any(arr):
            num, letter = arr[0], letters[0]
            new_arr = [letters[i] if i == num - 1 else arr[i] for i in range(len(arr))]
            arr = new_arr
            letters = letters[1:]
        return ''.join(arr)

    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        s = input()
        letters = collections.Counter(arr)
        if re.match(r'^' + ''.join(transform(arr, list(letters.keys()))), s):
            print("YES")
        else:
            print("NO")

