from itertools import combinations

def solve():
    def count_passwords(excluded_digits):
        excluded = set(excluded_digits)
        valid_combinations = set()
        for a, b in combinations(range(10), 2):
            if a not in excluded and b not in excluded:
                for c, d in combinations(range(10), 2):
                    if c not in excluded and d not in excluded:
                        valid_combinations.add((a, b, c, d))
        passwords = []
        for combo in valid_combinations:
            for i in range(2):
                for j in range(2):
                    if i == j:
                        continue
                    for k in range(10):
                        if k not in excluded:
                            passwords.append((combo[i], combo[j], k, k))
        return len(passwords)

    t = int(input())
    for _ in range(t):
        n = int(input())
        excluded_digits = list(map(int, input().split()))
        print(count_passwords(excluded_digits))

import itertools

def solve():
    def count_passwords(forbidden_digits):
        forbidden_set = set(forbidden_digits)
        valid_combinations = set()
        for a, b in itertools.combinations(range(10), 2):
            if a != b and a not in forbidden_set and b not in forbidden_set:
                valid_combinations.add((a, a, b, b))
        for length in range(3, 7):
            for combination in itertools.combinations(range(10), length):
                if len(set(combination)) == 2 and all(c not in forbidden_set for c in combination):
                    valid_combinations.add(tuple(combination))
        return len(valid_combinations)

    t = int(input())
    for _ in range(t):
        n = int(input())
        forbidden_digits = list(map(int, input().split()))
        print(count_passwords(forbidden_digits))

from itertools import combinations

def solve():
    for _ in range(int(input())):
        n = int(input())
        banned = sorted(list(map(int, input().split())))
        valid_combinations = set()
        for i in range(10):
            if i not in banned:
                valid_combinations.update(combinations(range(10), 4))
                for j in range(2, 5):
                    valid_combinations.discard((i,) + tuple(sorted(combination)) for combination in valid_combinations if combination.count(i) > j)
        print(len(valid_combinations))

import functools

def solve():
    def is_increasing(arr):
        return all(x <= y for x, y in zip(arr, arr[1:]))

    @functools.lru_cache(maxsize=None)
    def next_permutation(arr):
        n = len(arr)
        for i in range(n - 1, 0, -1):
            if arr[i - 1] < arr[i]:
                j = i
                for k in range(n - 1, i, -1):
                    if arr[k] > arr[i - 1]:
                        arr[i - 1], arr[k] = arr[k], arr[i - 1]
                        arr[i:] = sorted(arr[i:])
                        return True
        return False

    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        if is_increasing(arr):
            print("YES")
        elif next_permutation(arr):
            print("YES")
        else:
            print("NO")

