def compare_sizes(a, b):
    if a[0] == 'M':
        return b[0] not in ('M', 'L')
    elif b[0] == 'M':
        return a[0] in ('M', 'L')
    elif a[0] == 'X':
        return len(a) < len(b)
    elif b[0] == 'X':
        return len(b) > len(a)
    else:
        return a[1:] < b[1:]

