import math
import heapq

def solve():
    n = int(input())
    slices = []
    for _ in range(n):
        a, b = map(int, input().split())
        slices.append((a, b))

    slices.sort(key=lambda x: x[0])

    def rotate(a, b):
        return b, a

    def area(a, b):
        return a * b

    def perimeter(a, b):
        return 2 * (a + b)

    def compare(x, y):
        return x[2] - y[2]

    stack = []
    for a, b in slices:
        stack.append((perimeter(a, b), area(a, b), a, b))
        heapq.heapify(stack)

    total_area = 0
    total_perimeter = 0
    while stack:
        perimeter, area, a, b = heapq.heappop(stack)
        total_perimeter += perimeter
        total_area += area
        if not stack or stack[0][1] < total_area:
            break
        next_a, next_b = stack[0][3], stack[0][2]
        if next_a == a or next_b == b:
            continue
        rotated_next_a, rotated_next_b = rotate(next_a, next_b)
        if rotated_next_a == a or rotated_next_b == b:
            continue
        new_perimeter = perimeter + 2 * math.sqrt((a - rotated_next_a) ** 2 + (b - rotated_next_b) ** 2)
        new_area = area + area(rotated_next_a, rotated_next_b)
        heapq.heappush(stack, (new_perimeter, new_area, rotated_next_a, rotated_next_b))

    print(total_perimeter)

import heapq

def solve():
    def area(rect):
        return rect[0] * rect[1]

    def perimeter(rect):
        return 2 * (rect[0] + rect[1])

    def compare(a, b):
        return area(a) - area(b)

    def rotate(rect):
        return (rect[1], rect[0])

    def merge(a, b):
        return (a[0] + b[0], max(a[1], b[1]))

    def dfs(node, visited, graph):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited, graph)

    def solve_single(cheese):
        graph = {0: []}
        for i, (a, b) in enumerate(cheese):
            if i == 0:
                graph[0].append((perimeter((a, b)), i))
                continue
            for j in range(i - 1, -1, -1):
                if cheese[j][0] == b:
                    graph[i].append((perimeter((a, b)), j))
                    graph[j].append((perimeter((b, a)), i))
                    break
                if cheese[j][1] == a:
                    graph[i].append((perimeter(rotate(cheese[j])), j))
                    graph[j].append((perimeter(rotate(cheese[i])), i))
                    break
        visited = [False] * len(cheese)
        components = []
        for i in range(len(cheese)):
            if not visited[i]:
                heap = [(compare((cheese[i], node)) for node in range(len(cheese)) if not visited[node]]
                heapq.heapify(heap)
                component = []
                while heap:
                    node = heapq.heappop(heap)
                    if not visited[node]:
                        visited[node] = True
                        component.append(node)                        for neighbor in graph[node]:
                            heapq.heappush(heap, compare(neighbor, node))
                components.append(component)
        return min(perimeter(rotate(cheese[component[0]]) for component in components)

    cases = int(input())
    for _ in range(cases):
        n = int(input())
        cheese = []
        for _ in range(n):
            a, b = map(int, input().split())
            cheese.append((a, b))
        print(solve_single(cheese))

import heapq

def solve():
    def area(x, y, w, h):
        return x * y

    def perimeter(x, y, w, h):
        return 2 * (x + y + w + h)

    def compare(a, b):
        return b[1] - a[1]

    def rotate(x, y, w, h):
        return w, h, x, y

    def solve_case():
        n = int(input())
        slices = []
        for _ in range(n):
            x, y = map(int, input().split())
            slices.append((perimeter(x, y, x, 1), rotate(x, y, 1, 1)))
        heapq.heapify(slices)
        result = 0
        while slices:
            w, h, x, y = heapq.heappop(slices)
            if not result:
                result = w + 2 * x
            else:
                if y == result:
                    result += w + 2 * x
                else:
                    result += 2 * max(x, y)
                    result += min(x, y) + w
                    result += area(min(x, y), max(x, y), w, result - min(x, y) - max(x, y))
                    result += area(result - w, min(x, y), x, y)
        return result

    for _ in range(int(input())):
        print(solve_case())

import heapq

def solve():
    def area(x, y):
        return x * y

    def perimeter(x, y):
        return 2 * (x + y)

    def compare(a, b):
        return perimeter(a[0], a[1]) < perimeter(b[0], b[1])

    def rotate(x, y):
        return y, x

    def merge(a, b):
        return a[0] + b[0], max(a[1], b[1])

    def dfs(x, y, visited, height, area_so_far):
        if (x, y) in visited:
            return
        visited.add((x, y))
        area_so_far += area(x, y)
        height[0] = max(height[0], x)
        height[1] = max(height[1], y)
        for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nx, ny = x + dx, y + dy
            if 0 <= nx < height[0] and 0 <= ny < height[1]:
                dfs(nx, ny, visited, height, area_so_far)

    def solve_single(cheese):
        height = [0] * 2
        visited = set()
        area_so_far = 0
        for x, y in cheese:
            dfs(x, y, visited, height, area_so_far)
        return perimeter(height[0], height[1]) - area_so_far

    def solve_all():
        total_area = 0
        for _ in range(int(input())):
            n = int(input())
            cheese = []
            for _ in range(n):
                x, y = map(int, input().split())
                cheese.append((x, y))
            total_area += solve_single(cheese)
        print(total_area)

