    for _ in range(t):
        n = int(input())
        primes = set()
        primes_up_to_n = set(range(2, n + 1))
        p = 3
        while True:
            if p * p > n:
                break
            if p in primes:
                p += 2
                continue
            primes.add(p)
            primes_up_to_n.difference_update(set(range(p * p, n + 1, p)))
