import itertools

def solve():
    n, m = map(int, input().split())
    board = [[0] * m for _ in range(n)]

    def can_move(r, c):
        for dr, dc in [(1, 2), (2, 1), (-1, 2), (-2, 1), (-1, -2), (-2, -1), (1, -2), (2, -1)]:
            if 0 <= r + dr < n and 0 <= c + dc < m and board[r + dr][c + dc]:
                return False
        return True

    for r in range(n):
        for c in range(m):
            if not can_move(r, c):
                return r + 1, c + 1

    # If no isolated cells, return any cell on the board
    return min(enumerate(itertools.chain(*board)))[0] + 1, 1

import itertools

def solve():
    board_size = list(map(int, input().split()))
    n, m = board_size

    def is_isolated(r, c):
        for dr, dc in [(1, 2), (2, 1), (-1, 2), (-2, 1), (-1, -2), (-2, -1), (1, -2), (2, -1)]:
            if 0 < r + dr < n and 0 < c + dc < m:
                if (r + dr, c + dc) not in moves:
                    return False
        return True

    moves = set()
    for r in range(n):
        for c in range(m):
            moves.update(itertools.islice(itertools.product([r + 2*dr for dr in [1, -1]], [c + 2*dc for dc in [1, -1]]), 1, None))

    for r in range(n):
        for c in range(m):
            if is_isolated(r, c):
                return r+1, c+1

    # If no isolated cell is found, return any cell on the board
    return 1, 1

