import itertools

def solve():
    def knight_moves((x, y)):
        return [(x + 2 * dx, y + dy) for dx, dy in ((1, -2), (2, -1), (2, 1), (1, 2), (-1, 2), (-2, 1), (-2, -1), (-1, -2))]

    def is_isolated((x, y), board):
        moves = knight_moves((x, y))
        for mx, my in moves:
            if 0 <= mx < len(board) and 0 <= my < len(board[0]) and (mx, my) not in board:
                return False
        return True

    def find_isolated(board):
        for x in range(len(board)):
            for y in range(len(board[0])):
                if is_isolated((x, y), board):
                    return (x, y)
        return (0, 0)

    def find_any(board):
        return (0, 0) if not board else list(itertools.product(range(len(board)), range(len(board[0]))))[0]

    def main():
        for _ in range(int(input())):
            n, m = map(int, input().split())
            board = [[0] * m for _ in range(n)]
            print(*find_isolated(board) if any(is_isolated(p, board) for p in itertools.product(range(n), range(m))) else find_any(board))

    main()

import sys

def knight_moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]

def is_valid(board, row, col):
    n, m = len(board), len(board[0])
    if row < 1 or row > n or col < 1 or col > m:
        return False
    for move in knight_moves:
        new_row, new_col = row + move[0], col + move[1]
        if board[new_row][new_col] == 1:
            return True
    return False

def dfs(board, row, col, visited):
    if not is_valid(board, row, col):
        return
    visited[row][col] = True
    for move in knight_moves:
        new_row, new_col = row + move[0], col + move[1]
        if not visited[new_row][new_col]:
            dfs(board, new_row, new_col, visited)

