import functools
import operator

def solve():
    def dfs(node, skills, dp):
        if node == len(skills):
            return 0

        max_damage = 0
        for i in range(node, len(skills)):
            if skills[i] != skills[node - 1]:
                dp[i] = dfs(i + 1, skills, dp) * 2 + skills[i][1]
                max_damage = max(max_damage, dp[i])

        dp[node] = skills[node][1] if node == 0 else max_damage
        return dp[node]

    @functools.lru_cache(maxsize=None)
    def memo(i):
        return dfs(i, skills, [0] * len(skills))

    while True:
        n = int(input())
        if not n:
            break
        skills = list(map(lambda x: (x, int(x[2:])), input().split()))
        print(memo(0))

