def solve():
    def combine(x, y):
        if x[0] == y[0]:
            return (x[0], x[1] + y[1])
        else:
            return (2 * min(x[1], y[1]), x[0])

    @functools.lru_cache(maxsize=None)
    def dp(i, types, damages):
        if i == 0:
            return 0
        max_damage = 0
        for j in range(i):
            if types[j] != types[i - 1]:
                max_damage = max(max_damage, dp(j) + damages[i - 1] * 2)
            max_damage = max(max_damage, dp(j) + damages[i - 1])
        max_damage = max(max_damage, damages[i - 1])
        return max_damage

    t = int(input())
    for _ in range(t):
        n = int(input())
        types = list(map(int, input().split()))
        damages = list(map(int, input().split()))
        print(dp(n, types, damages))

