        for i in range(n):
            for j in range(i, -1, -1):
                if skills[i] != skills[j]:
                    dp[i][skills[i]] = max(dp[j][skills[j]] + 2 * damages[i], dp[i][skills[i]])
                else:
                    dp[i][skills[i]] = dp[j][skills[j]] + damages[i]
        return max(dp[-1])

