def solve():
    def min_ops(a: List[int], b: List[int]):
        count = 0
        for i in range(len(a)):
            if a[i] != b[i]:
                count += 1
                a[i] = 1 - a[i]
        return count if a == b else float('inf')

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        b = list(map(int, input().split()))
