from typing import List

def solve():
    def xor(a: List[int], b: List[int]) -> int:
        return sum(x ^ y for x, y in zip(a, b))

    def min_ops(a: List[int], b: List[int]) -> int:
        diff = xor(a, b)
        return diff if diff else len(a) - sum(1 for i, x in enumerate(a) if x != b[i])

    def main():
        t = int(input())
        for _ in range(t):
            n = int(input())
            a = list(map(int, input().split()))
            b = list(map(int, input().split()))
            print(min_ops(a, b))

    main()

from collections import Counter

def solve():
    def min_ops(a, b):
        if a == b:
            return 0
        c = Counter(a)
        d = Counter(b)
        ops = 0
        for k in c.keys():
            if k not in d:
                return -1
            ops += min(c[k], d[k])
        return ops

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        b = list(map(int, input().split()))
        print(min_ops(a, b))

import math

def solve():
    def days_off(n, days_off_indices):
        working_segments = [(days_off_indices[i], days_off_indices[i+1] - 1) for i in range(len(days_off_indices) - 1)]
        working_segments.append((days_off_indices[-1], n - 1))
        return working_segments

    def min_diff(working_segments):
        return max(abs(x - y) for x, y in zip(working_segments, working_segments[1:] + working_segments[:1]))

    def solve_helper(n, days_off_count, days_off_indices, memo={}):
        if days_off_count == 2:
            return min_diff(days_off(n, days_off_indices))
        if (n, days_off_count, days_off_indices) in memo:
            return memo[(n, days_off_count, days_off_indices)]
        result = float('inf')
        for i in range(1, n):
            if i in days_off_indices:
                continue
            for j in range(i + 1, n):
                if j in days_off_indices:
                    continue
                days_off_indices_copy = days_off_indices.copy()
                days_off_indices_copy[0] = i
                days_off_indices_copy.append(j)
                result = min(result, solve_helper(n, days_off_count - 1, days_off_indices_copy, memo))
        memo[(n, days_off_count, days_off_indices)] = result
        return result

    def solve_n(n):
        return solve_helper(n, 3, [0], {})

    t = int(input())
    for _ in range(t):
        n = int(input())
        print(solve_n(n))

