        if days_off_count == 2:
            return min_diff(days_off(n, days_off_indices))
        for i in range(1, n):
            if i not in days_off_indices:
                for j in range(i+1, n):
                    if j not in days_off_indices:
                        days_off_indices.append(i)
                        days_off_indices.append(j)
                        result = solve_util(n, days_off_count - 1, days_off_indices)
                        days_off_indices.pop()
