import math

def solve():
    def days_off(n, days_off_indices):
        working_segments = [(days_off_indices[i], days_off_indices[i+1] - 1) for i in range(len(days_off_indices) - 1)]
        working_segments.append((days_off_indices[-1], n - 1))
        return working_segments

    def min_diff(working_segments):
        return max(abs(x - y) for x, y in zip(working_segments, working_segments[1:] + working_segments[:1]))

    def backtrack(n, days_off_indices, best_diff):
        if len(days_off_indices) == 3:
            working_segments = days_off(n, days_off_indices)
            current_diff = min_diff(working_segments)
            best_diff = max(best_diff, current_diff)
            return

        for i in range(n - 2, -1, -1):
            if i not in days_off_indices:
                days_off_indices.append(i)
                backtrack(n, days_off_indices, best_diff)
                days_off_indices.pop()

    best_diff = 0
    backtrack(n, [], best_diff)
    return best_diff

