def solve():
    def days_off(n):
        days = [0] * n
        days[0] = 1
        days[n-1] = 1
        days[n-2] = 1
        for i in range(2, n-1):
            for j in range(i+2, n):
                if days[i-1] + j - i <= n and days[j] + i - j <= n:
                    days[i] = 1
                    break
        return days

    def max_diff(days):
        segments = []
        for i in range(len(days)):
            if days[i] == 0:
                segments.append(i - segments[-1] - 1)
        return max(abs(x - y) for x, y in zip(segments, segments[1:] + segments[:1]))

    t = int(input())
    for _ in range(t):
        n = int(input())
        days = days_off(n)
        print(max_diff(days))

