def solve():
    def days_off(n):
        days = [0] * n
        days[0] = 1
        days[n - 1] = 1
        days[1] = 0
        for i in range(2, n):
            days[i] = max(days[i - 2], days[i - 3]) + 1
        return days

    def max_diff(days):
        segments = []
        for i in range(len(days)):
            if days[i] == 0:
                segments.append(sum(days[j] for j in range(i, len(days))))
        return max(gcd(*segments), 1)

    t = int(input())
    for _ in range(t):
        n = int(input())
        days = days_off(n)
        print(max_diff(days))

