def solve():
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def extend_gcd(a, b, x, y):
        if a == 0:
            return (0, 1, 0, 0)
        else:
            q, x1, y1, x0 = extend_gcd(b % a, a, y, x - (b // a) * y)
            return (q, x0 - q * x1, y0 - q * y1, x1)

    def extended_euclidean(a, b):
        q, x, y, x0 = extend_gcd(abs(a), abs(b), 0, 1)
        if a < 0:
            x = -x
        if b < 0:
            y = -y
        return (q, x, y)

    def get_max_sum(a):
        n = len(a)
        dp = [[0] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = a[i]
            for j in range(i + 1, n):
                g = gcd(a[i], a[j])
                if g > 1:
                    q, x, y = extended_euclidean(a[i], g)
                    dp[i][j] = dp[i][i] * x * dp[j][j] * y
                else:
                    for k in range(i + 1, j):
                        dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j])
        return max(reduce(lambda x, y: x + y, dp[0]))

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        print(2022 * get_max_sum(a))

from collections import defaultdict

def solve():
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def extend_gcd(a, b):
        if not b:
            return (1, 0, 0, a)
        else:
            x, y, x1, y1 = extend_gcd(b, a % b)
            return (y1, x - y * (a // b), x1, y)

    def solve_subarray(arr, start, end):
        if start == end:
            return arr[start], 1
        mid = (start + end) // 2
        x1, y1, _, _ = extend_gcd(arr[start], arr[mid])
        x2, y2, _, _ = extend_gcd(arr[mid + 1], arr[end])
        if x1 * x2 == y1 * y2:
            prod = arr[start] * arr[mid] * arr[mid + 1] * arr[end]
            return solve_subarray(arr[:mid], start, mid) + solve_subarray(arr[mid + 1:], mid + 1, end), prod
        if x1 * y2 > y1 * x2:
            return solve_subarray(arr, start, mid), arr[start:mid + 1].index(y1 // y2) * arr[mid + 1:end].index(x1 // x2) * arr[start] * arr[mid] * arr[mid + 1] * arr[end]
        return solve_subarray(arr, mid + 1, end), arr[start:mid + 1].index(y2 // y1) * arr[start:mid].index(x2 // x1) * arr[start] * arr[mid] * arr[mid + 1] * arr[end]

    def solve_array(arr):
        n = len(arr)
        dp = defaultdict(lambda: defaultdict(int))
        for i in range(n):
            for j in range(i + 1, n):
                g = gcd(arr[i], arr[j])
                dp[i][j] = dp[i][j - 1] + arr[j] // g
                dp[j][i] = dp[j + 1][i] + arr[i] // g
        max_sum = 0
        for i in range(1, n):
            for j in range(i + 1, n):
                x, y = extend_gcd(arr[i], arr[j])
                max_sum = max(max_sum, dp[i][j - 1] * y + dp[j][i - 1] * x)
        return max_sum

    for _ in range(int(input())):
        n = int(input())
        arr = list(map(int, input().split()))
        print(2022 * solve_array(arr) + solve_subarray(arr, 0, n - 1)[1])

