def solve():
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def extended_euclidean_algorithm(a, b):
        if b == 0:
            return (1, 0, a)
        else:
            g, y, x = extended_euclidean_algorithm(b, a % b)
            return (g, x - (a // b) * x, y)

    def get_factors(n):
        factors = []
        i = 2
        while i * i <= n:
            if n % i:
                i += 1
            else:
                factors.append(i)
                n //= i
        if n > 1:
            factors.append(n)
        return factors

    def solve_array(a):
        n = len(a)
        max_sum = 0
        for i in range(n):
            for j in range(i + 1, n):
                product = a[i] * a[j]
                factors_product = get_factors(product)
                if len(factors_product) > 2:
                    continue
                g, x, y = extended_euclidean_algorithm(factors_product[0], factors_product[1] if len(factors_product) == 2 else 1)
                if g > max_sum:
                    max_sum = g
                    new_a = [x if i == k else y if j == k else a[k] for k in range(n)]
                    if all(new_a[i] * new_a[j] == product for i in range(n) for j in range(i + 1, n)):
                        return new_a
        return a

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        a = solve_array(a)
        print(2022 * sum(a))

