import heapq

def solve():
    def min_cost(n, c, a):
        planets = sorted(set(a))
        costs = [0] * (max(planets) + 1)
        for planet in a:
            costs[planet] += 1
        for planet in planets:
            costs[planet] = min(costs[planet], 1 + costs[planet - 1])
        q = [(costs[planet], planet) for planet in planets]
        heapq.heapify(q)
        result = 0
        while q:
            cost, planet = heapq.heappop(q)
            if cost <= c:
                result += cost
                if planet != 1:
                    result += min_cost(n - 1, c, [a_i for a_i in a if a_i > planet])
            else:
                result += c
                if planet != 1:
                    result += min_cost(n - len([a_i for a_i in a if a_i == planet]), c, [])
        return result

    t = int(input())
    for _ in range(t):
        n, c = map(int, input().split())
        a = list(map(int, input().split()))
        print(min_cost(n, c, a))

