import collections

def solve():
    n = int(input())
    graph = collections.defaultdict(list)
    for _ in range(n):
        cnt = list(map(int, input().split()))
        for i in range(len(cnt)):
            for j in range(i):
                if cnt[i] > 0 and cnt[j] > 0 and i != j:
                    graph[i].append(j)
                    graph[j].append(i)

    for color in range(1, n+1):
        if not graph[color]:
            return color

    # Check for cycles in the graph
    visited = set()
    stack = [(color, -1) for color in graph]
    while stack:
        color, last_color = stack.pop()
        if color in visited:
            return -1
        visited.add(color)
        for neighbor in graph[color]:
            if neighbor != last_color:
                stack.append((neighbor, color))

    # If no cycles are found, return the color of the last ball we saw
    return last_color

