def solve():
    def min_moves(image):
        colors = set()
        for row in image:
            colors.update(row)
        if len(colors) == 1:
            return 0

        moves = 0
        for color in colors:
            pairs = list(itertools.combinations(image, 2))
            for pair in pairs:
                if pair[0] == pair[1] and len(set(pair[0]) & set(pair[1])) == 1:
                    moves += 1
                    for row in image:
                        if row[0] == color:
                            row[0] = pair[0][0] if pair[0][0] != pair[1][0] else pair[1][0]
                        if row[1] == color:
                            row[1] = pair[0][1] if pair[0][1] != pair[1][1] else pair[1][1]
                    break
        return moves

    t = int(input())
    for _ in range(t):
        image = list(map(str, input().split()))
        print(min_moves(image))

