def solve():
    def max_beauty(arr):
        n = len(arr)
        @functools.lru_cache(maxsize=None)
        def dfs(l, r):
            if l == r:
                return 0
            if r - l + 1 == 1:
                return max(arr[l], arr[r]) - min(arr[l], arr[r])
            max_left = max(arr[:l])
            max_right = max(arr[r+1:])
            min_left = min(arr[:l])
            min_right = min(arr[r+1:])
            return max(max_left + max_right - min_left - min_right, dfs(l+1, r-1))
        return max(dfs(1, i) for i in range(2, n))

    for _ in range(int(input())):
        n = int(input())
        arr = list(map(int, input().split()))
        print(max_beauty(arr))

