import sys

def is_valid_move(x, y, n, m, board):
    if x < 0 or x >= n or y < 0 or y >= m:
        return False
    if board[x][y] == 'R':
        return False
    if board[x][y] == 'G':
        for i in range(1, 4):
            if (x + i) % 2 == 0 and 0 <= y + i < m and board[x + i][y + i] != 'R':
                return True
            if (y + i) % 2 == 0 and 0 <= x + i < n and board[x + i][y] != 'R':
                return True
    return False

def solve():
    n, m = map(int, input().split())
    board = [['.' for _ in range(m)] for _ in range(n)]
    board[0][0] = 'G'

    burenka_turn = True
    while True:
        if burenka_turn:
            x, y = 0, 0
            while not is_valid_move(x, y, n, m, board):
                if not is_valid_move(x + 1, y, n, m, board):
                    burenka_turn = False
                    break
                x += 1
            if not is_valid_move(x, y, n, m, board):
                print("Tonya")
                return
            board[x][y] = 'B'
            burenka_turn = False
        else:
            x, y = 0, m - 1
            while not is_valid_move(x, y, n, m, board):
                if not is_valid_move(x, y - 1, n, m, board):
                    burenka_turn = True
                    break
                y -= 1
            if not is_valid_move(x, y, n, m, board):
                print("Burenka")
                return
            board[x][y] = 'T'
            burenka_turn = True

