from collections import deque

def bfs(board):
    visited = set()
    q = deque([(0, 0)])
    visited.add((0, 0))

    moves = [(0, 1), (1, 0)]

    while q:
        x, y = q.popleft()

        for dx, dy in moves:
            nx, ny = x + dx * 2, y + dy * 2

            if 0 <= nx < board[0] and 0 <= ny < board[1] and (nx, ny) not in visited:
                if not board[nx][ny]:
                    return "Burenka"
                visited.add((nx, ny))
                q.append((nx, ny))

    return "Tonya"

