            if 0 <= next_cell[0] < board[0] and 0 <= next_cell[1] < board[1] and (not visited[next_cell] or not visited[next_cell][-1]):
                visited[next_cell] = path + [(next_cell, [dx, dy])]
                queue.append((next_cell, path + [(next_cell, [dx, dy])]))

