    while queue:
        current = queue.popleft()
        x, y = current
        if (x == board[0] - 1 and y == board[1] - 1):
            return 'Burenka'

        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + dx * 3, y + dy * 3
            if 0 <= nx < board[0] and 0 <= ny < board[1] and not visited[nx][ny]:
                visited[nx][ny] = True
                queue.append((nx, ny))

