import sys

def bfs(board, start, visited, dx, dy):
    queue = [(start[0], start[1], 0)]
    visited[start[0]][start[1]] = True

    while queue:
        x, y, moves = queue.pop(0)

        if (x, y) == (board[1] - 1, board[0] - 1):
            return moves % 2 == 0

        for i in range(1, min(board[0], board[1]) + 1, 2):
            nx = x + i * dx
            ny = y + i * dy

            if 0 <= nx < board[0] and 0 <= ny < board[1] and not visited[nx][ny]:
                visited[nx][ny] = True
                queue.append((nx, ny, moves + 1))

    return False

