def solve():
    def lcm_gcd(a, b):
        if a < b:
            a, b = b, a
        while b != 0:
            a, b = b, a % b
        return a, b

    def count_pairs(n):
        count = 0
        for a in range(1, n + 1):
            lcm, gcd = lcm_gcd(a, n)
            if lcm <= 3 and gcd <= 1:
