import itertools

def solve():
    def find_swap(perm):
        for i, j in itertools.combinations(range(len(perm)), 2):
            if perm[i] != i and perm[j] != j:
                return i, j
        return None

    def swap(perm, i, j):
        perm[i], perm[j] = perm[j], perm[i]

    def fixedness(perm):
        return sum(1 for i, val in enumerate(perm) if i == val)

    def find_longest_chain(n):
        chain = [list(range(1, n + 1))]
        visited = set()
        visited.add(tuple(chain[-1]))
        while True:
            next_chain = []
            for perm in chain:
                swap_pos = find_swap(perm)
                if swap_pos is None or tuple(perm) in visited:
                    continue
                new_perm = list(perm)
                swap(new_perm, swap_pos[0], swap_pos[1])
                if fixedness(new_perm) < fixedness(perm):
                    next_chain.append(new_perm)
                    visited.add(tuple(new_perm))
            if not next_chain:
                break
            chain = next_chain
        return chain

    t = int(input())
    for _ in range(t):
        n = int(input())
        chain = find_longest_chain(n)
        print(len(chain))
        print(*chain, sep='\n')

from itertools import permutations, combinations

def solve(n):
    def fixedness(perm):
        return sum(i == perm[i] for i in range(n))

    def swap(perm, i, j):
        return list(perm)[:i] + list(perm)[j] + list(perm)[i:j] + list(perm)[i:]

    def find_swap(perm):
        for i, j in combinations(range(n), 2):
            if fixedness(swap(perm, i, j)) < fixedness(perm):
                return i, j
        return None

    chain = [list(range(1, n + 1))]
    while True:
        next_swap = find_swap(chain[-1])
        if next_swap is None:
            break
        chain.append(swap(chain[-1], next_swap[0], next_swap[1]))
    return len(chain), chain

