        end = (n - 1, m - 1)
        grid[start] = '.'
        grid[end] = '.'

        graph = create_graph(grid)
        distances = dijkstra(graph, start, (n - 1, 0))
        teleport_distance = dijkstra(graph, (n - 1, 0), (n - 1, m - 1))
        distances_from_end = dijkstra(graph, (n - 1, m - 1), end)

