def solve():
    def find_min_number(s):
        digits = set()
        for digit in str(s):
            digits.add(int(digit))
        if len(digits) > 9:
            return -1
        candidates = list(combinations(range(1, 10), len(digits)))
        min_sum = math.inf
        min_number = ""
        for candidate in candidates:
            sum_ = sum(candidate)
            if sum_ == s and sum_ < min_sum:
                min_sum = sum_
                min_number = "".join(map(str, candidate))
        return min_number if min_sum == s else -1

