        return False

    def bfs(boxes):
        q = [(0, (0, 0))]
        visited = set()
        visited.add((0, 0))
        while q:
            moves, pos = heapq.heappop(q)
            if all(map(can_move, *zip(*pos))):
                for new_pos in [move(pos[0], pos[1]), move(pos[0], pos[1] + 1), move(pos[0] + 1, pos[1]), move(pos[0] + 1, pos[1] + 1)]:
                    if new_pos not in visited:
                        visited.add(new_pos)
                        q.append((moves + 1, new_pos))
        return moves

    return bfs(boxes)

