import heapq

def solve():
    n = int(input())
    boxes = collections.defaultdict(list)
    for _ in range(n):
        x, y = map(int, input().split())
        boxes[x if x else y].append((x, y))

    def manhattan_distance(x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2)

    def dijkstra(start):
        distances = {start: 0}
        queue = [(0, start)]
        while queue:
            d, current = heapq.heappop(queue)
            for next in [(current[0] + manhattan_distance(*current, *box) if box else float('inf'), current, box) for box in boxes.values()]:
                if next[1] not in distances or next[0] < distances[next[1]]:
                    distances[next[1]] = next[0]
                    heapq.heappush(queue, next)

        return distances

    distances = dijkstra((0, 0))
    total_distance = sum(distances[box] for box in boxes.values())
    print(total_distance)

