from 1 to n in non-increasing order of their smallest prime factors. Then, we can construct the permutation by iteratively appending the smallest number that does not divide any of the numbers already in the permutation.

Here is the Python code for the solution:

```python
from functools import reduce
from math import gcd

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            factors.append(i)
            n //= i
    if n > 1:
        factors.append(n)
    return factors

def smallest_prime_factor(n):
    return min(prime_factors(n))

def solve():
    n = int(input())
    nums = list(range(1, n + 1))
    nums.sort(key=smallest_prime_factor, reverse=True)
    permutation = []
    for num in nums:
        for i in range(len(permutation)):
            if num % permutation[i] == 0:
                break
        else:
            permutation.append(num)
    print(*permutation)

import sys

def solve():
    def find_cycle(perm):
        slow, fast = 0, 0
        while True:
            slow = perm[slow]
            fast = perm[perm[fast]]
            if slow == fast:
                break

        if fast == perm[-1]:
            return None

        start = slow
        end = fast
        while start != end:
            start, end = perm[start], perm[end]
            perm[start], perm[end] = perm[end], perm[start]
        return perm

    for _ in range(int(input())):
        n = int(input())
        perm = list(range(1, n + 1))
        perm = find_cycle(perm)
        if perm is None:
            print(*perm)
        else:
            print(*reversed(perm))

