def solve():
    n = int(input())
    if n == 1:
        print(1)
        return

    adj_list = [[] for _ in range(n)]
    for i in range(1, n):
        adj_list[i].append((i, i - 1))
        adj_list[i - 1].append((i - 1, i))

    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(1, n):
        dist[i][i] = 0

    for k in range(1, n):
        for i in range(1, n):
            for j in range(1, n):
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    parent = [None] * n
    for k in range(1, n):
        for i in range(1, n):
            for j in range(1, n):
                if dist[i][j] == dist[i][k] + dist[k][j]:
                    parent[j] = k

    stack = [n - 1]
    permutation = [0] * n
    while stack:
        i = stack.pop()
        permutation[i] = i
        if i != parent[i]:
            stack.append(parent[i])

    print(*permutation)

