def solve():
    def check(h1, h2):
        return all(h2[i] - h1[i] >= x for i in range(len(h1)))

    def find_gap(h):
        return max(h) - min(h)

    def find_max_height(h1, h2, x):
        return max(h1) + x if find_gap(h1) >= x else max(h2) - x

    def find_min_height(h1, h2, x):
        return min(h1) - x if find_gap(h1) >= x else min(h2) + x

    def solve_row(h, x):
        if len(h) == 1:
            return h[0] >= x
        gap = find_gap(h)
        if gap >= x:
            return True
        max_height = find_max_height(h[:len(h) // 2], h[len(h) // 2:], x)
        min_height = find_min_height(h[:len(h) // 2], h[len(h) // 2:], x)
        return any(solve_row(h1, x) for h1 in zip(h[:len(h) // 2], repeat(min_height, len(h) // 2))) or any(solve_row(h1, x) for h1 in zip(h[len(h) // 2:], repeat(max_height, len(h) // 2)))

    def solve_test_case():
        n, x = map(int, input().split())
        h = list(map(int, input().split()))
        return "YES" if solve_row(h[:n], x) and solve_row(h[n:], x) else "NO"

    for _ in range(int(input())):
        print(solve_test_case())

