import collections

def solve():
    def rotate(num, direction):
        if direction == 'U':
            return (num + 1) % 10
        else:
            return (num - 1) % 10

    def solve_wheel(moves, initial_num):
        num = initial_num
        for move in moves:
            if move == 'U':
                num = rotate(num, 'U')
            else:
                num = rotate(num, 'D')
        return num

    test_cases = int(input())
    for _ in range(test_cases):
        n = int(input())
        final_sequence = list(map(int, input().split()))
        moves = []
        for _ in range(n):
            moves_str = input()
            moves += [(moves_str.count('U'), moves_str) for _ in range(moves_str.count('U'))] + [(moves_str.count('D'), moves_str) for _ in range(moves_str.count('D'))]
        initial_sequence = [solve_wheel(moves[i], i) for i in range(n)]
        print(' '.join(map(str, initial_sequence)))

