import itertools

def solve():
    n = int(input())
    dp = [[0] * n for _ in range(n)]
    for i in range(1, n):
        for j in range(1, n):
            for k in range(1, n):
                if i * k == j * (i + 1):
                    dp[j][i] = max(dp[j][i], dp[j - 1][i - 1] + 1)
    max_cost = max(dp[n - 1])
    for i in range(n - 1, -1, -1):
        if dp[i][n - 1] == max_cost:
            yield n - 1
            for j in range(i - 1, -1, -1):
                yield j + 1
            break

