def solve():
    t = int(input())
    for _ in range(t):
        a = [list(map(int, input().split())) for _ in range(2)]
        visited = defaultdict(lambda: False)
        moves = 0

        for i in range(2):
            for j in range(2):
                if a[i][j] and not visited[i, j]:
                    dfs(a, i, j)
                    moves += 1

        def dfs(grid, x, y):
            if x < 0 or x >= 2 or y < 0 or y >= 2 or grid[x][y] == 0 or visited[x, y]:
                return
            visited[x, y] = True
            grid[x][y] = 0
            dfs(grid, x - 1, y)
            dfs(grid, x + 1, y)
            dfs(grid, x, y - 1)
            dfs(grid, x, y + 1)

        print(moves)

