def solve():
    n, m = map(int, input().split())
    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1

    for i in range(1, n):
        for j in range(min(i, m)):
            dp[i][j] = dp[i - 1][j] + (j + 1)

    for j in range(1, m):
        for i in range(min(i, n)):
            dp[i][j] += dp[i][j - 1] + (i + 1)

    return dp[-1][-1]

