def solve():
    def dp(n, m):
        dp = [[float('inf')] * m for _ in range(n)]
        dp[0][0] = 0

        for i in range(1, n):
            dp[i][0] = dp[i - 1][0] + (i - 1) * m

        for j in range(1, m):
            dp[0][j] = dp[0][j - 1] + j

        for i in range(1, n):
            for j in range(1, m):
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + (i - 1) * m + j

        return dp[n - 1][m - 1]

