from collections import defaultdict

def solve():
    n, m = map(int, input().strip().split())
    dp = defaultdict(int)
    dp[(1, 1)] = 0

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if (i, j) == (n, m):
                break
            dp[(i, j)] = min(dp[(i + 1, j)] + (i - 1) * m, dp[(i, j + 1)] + j)

    print(dp[(n, m)])
